ALTER TABLE procedures ADD COLUMN IF NOT EXISTS purpose TEXT;                                       -- Desired outcome and scope of the procedure.
ALTER TABLE procedures ADD COLUMN IF NOT EXISTS target TEXT;                                        -- Thing or population on which the procedure acts; maps to pko:hasProcedureTarget.
