ALTER TABLE procedure_versions ADD COLUMN IF NOT EXISTS modified_by_agent TEXT;                     -- Agent that last modified the version; maps to pko:wasModifiedBy.
ALTER TABLE procedure_versions ADD COLUMN IF NOT EXISTS new_version_motivation TEXT;                -- Reason for the new version; maps to pko:newVersionMotivation.
ALTER TABLE procedure_versions ADD COLUMN IF NOT EXISTS changelog_description TEXT;                 -- Semantic change description; maps to pko:changelogDescription.
ALTER TABLE procedure_versions ADD COLUMN IF NOT EXISTS is_current BOOLEAN;                         -- TRUE when this is the current version.
ALTER TABLE procedure_versions ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                    -- The evaluation context this row's time-dependent witnesses are judged under.
ALTER TABLE procedure_versions ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                     -- Exact PKO class IRI.
