COMMENT ON COLUMN procedure_versions.new_version_motivation IS 'Reason for the new version; maps to pko:newVersionMotivation.';
COMMENT ON COLUMN procedure_versions.changelog_description IS 'Semantic change description; maps to pko:changelogDescription.';
COMMENT ON COLUMN procedure_versions.is_current IS 'TRUE when this is the current version.';
