-- ----------------------------------------------------------------------------
-- Steps: Version-scoped units of work. Atomic steps map to pplan:Step; composite steps map to pplan:MultiStep. The specification is never conflated with execution.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS steps (
  step_id                             TEXT                 PRIMARY KEY          -- Stored logical identifier for one Steps row.
);
ALTER TABLE steps ADD COLUMN IF NOT EXISTS procedure_version TEXT;                                  -- Procedure version containing the step; maps to pko:hasStep/pplan:isStepOfPlan.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS step_number TEXT;                                        -- Stable sequence label; maps to pko:stepNumber.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS title TEXT;                                              -- Human-readable step title.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS step_kind TEXT;                                          -- Atomic or MultiStep.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS assigned_role TEXT;                                      -- Role responsible for the step.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS instruction TEXT;                                        -- Normative step instruction.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS expected_duration_minutes INTEGER;                       -- Expected duration represented as an OWL-Time duration in semantic projections.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS expertise_level TEXT;                                    -- PKO expertise level: Junior, Senior, Expert, or Master.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS requires_human_confirmation BOOLEAN;                     -- TRUE when a human must confirm the step; maps to pko:wasConfirmedBy at execution.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS control_kind TEXT;                                       -- What kind of control this step is: Preparation, Approval, LegalReview, Verification, Extraction, Publication, Retrospective, or None. That policy-04 is a legal review is a property OF policy-04, not of a formula that happens to name it; storing it as data makes downstream predicates portable to procedures that do not exist yet.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                                  -- Exact P-Plan class IRI.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS parent_step TEXT;                                        -- The multi-step this step sits in (pko:isStepOfMultiStep).
ALTER TABLE steps ADD COLUMN IF NOT EXISTS first_child_step TEXT;                                   -- For a multi-step, its first sub-step (pko:hasFirstStep).
ALTER TABLE steps ADD COLUMN IF NOT EXISTS verifies_step TEXT;                                      -- For a verification step, the step it checks (pko:isStepVerificationOf).
ALTER TABLE steps ADD COLUMN IF NOT EXISTS remedy_for_error TEXT;                                   -- Error this step remedies (pko:addressesError).
ALTER TABLE steps ADD COLUMN IF NOT EXISTS calls_procedure TEXT;                                    -- Sub-procedure this step invokes.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS isolates_energy_source TEXT;                             -- Energy source this step isolates.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS prerequisite_step TEXT;                                  -- Step whose completion this step requires first (the requires relation).
ALTER TABLE steps ADD COLUMN IF NOT EXISTS min_repetitions INTEGER;                                 -- Minimum times the step runs in one execution (pko:minRepetitions).
ALTER TABLE steps ADD COLUMN IF NOT EXISTS max_repetitions INTEGER;                                 -- Maximum times the step may run in one execution (pko:maxRepetitions).
ALTER TABLE steps ADD COLUMN IF NOT EXISTS description TEXT;                                        -- Longer description of the step (dct:description).
ALTER TABLE steps ADD COLUMN IF NOT EXISTS stage TEXT;                                              -- Stage the step is grouped in.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS detail_level TEXT;                                       -- Activity (bundles many actions), Task, or Action (a single physical or system action).
ALTER TABLE steps ADD COLUMN IF NOT EXISTS is_declared_first_step BOOLEAN;                          -- TRUE for the step its version declares as its first step.
ALTER TABLE steps ADD COLUMN IF NOT EXISTS is_declared_fallback_step BOOLEAN;                       -- TRUE for the step its version declares as its fallback step.
COMMENT ON TABLE steps IS 'Version-scoped units of work. Atomic steps map to pplan:Step; composite steps map to pplan:MultiStep. The specification is never conflated with execution.';
COMMENT ON COLUMN steps.step_id IS 'Stored logical identifier for one Steps row.';
COMMENT ON COLUMN steps.procedure_version IS 'Procedure version containing the step; maps to pko:hasStep/pplan:isStepOfPlan.';
COMMENT ON COLUMN steps.step_number IS 'Stable sequence label; maps to pko:stepNumber.';
COMMENT ON COLUMN steps.title IS 'Human-readable step title.';
COMMENT ON COLUMN steps.step_kind IS 'Atomic or MultiStep.';
COMMENT ON COLUMN steps.assigned_role IS 'Role responsible for the step.';
COMMENT ON COLUMN steps.instruction IS 'Normative step instruction.';
COMMENT ON COLUMN steps.expected_duration_minutes IS 'Expected duration represented as an OWL-Time duration in semantic projections.';
COMMENT ON COLUMN steps.expertise_level IS 'PKO expertise level: Junior, Senior, Expert, or Master.';
COMMENT ON COLUMN steps.requires_human_confirmation IS 'TRUE when a human must confirm the step; maps to pko:wasConfirmedBy at execution.';
COMMENT ON COLUMN steps.control_kind IS 'What kind of control this step is: Preparation, Approval, LegalReview, Verification, Extraction, Publication, Retrospective, or None. That policy-04 is a legal review is a property OF policy-04, not of a formula that happens to name it; storing it as data makes downstream predicates portable to procedures that do not exist yet.';
COMMENT ON COLUMN steps.semantic_type_iri IS 'Exact P-Plan class IRI.';
COMMENT ON COLUMN steps.parent_step IS 'The multi-step this step sits in (pko:isStepOfMultiStep).';
COMMENT ON COLUMN steps.first_child_step IS 'For a multi-step, its first sub-step (pko:hasFirstStep).';
COMMENT ON COLUMN steps.verifies_step IS 'For a verification step, the step it checks (pko:isStepVerificationOf).';
COMMENT ON COLUMN steps.remedy_for_error IS 'Error this step remedies (pko:addressesError).';
COMMENT ON COLUMN steps.calls_procedure IS 'Sub-procedure this step invokes.';
COMMENT ON COLUMN steps.isolates_energy_source IS 'Energy source this step isolates.';
COMMENT ON COLUMN steps.prerequisite_step IS 'Step whose completion this step requires first (the requires relation).';
COMMENT ON COLUMN steps.min_repetitions IS 'Minimum times the step runs in one execution (pko:minRepetitions).';
COMMENT ON COLUMN steps.max_repetitions IS 'Maximum times the step may run in one execution (pko:maxRepetitions).';
COMMENT ON COLUMN steps.description IS 'Longer description of the step (dct:description).';
COMMENT ON COLUMN steps.stage IS 'Stage the step is grouped in.';
COMMENT ON COLUMN steps.detail_level IS 'Activity (bundles many actions), Task, or Action (a single physical or system action).';
COMMENT ON COLUMN steps.is_declared_first_step IS 'TRUE for the step its version declares as its first step.';
COMMENT ON COLUMN steps.is_declared_fallback_step IS 'TRUE for the step its version declares as its fallback step.';

-- ----------------------------------------------------------------------------
-- StepTransitions: Directed control-flow edges represented as first-class pko:Transition instances with fromStep/toStep and next/alternative/fallback semantics.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS step_transitions (
  step_transition_id                  TEXT                 PRIMARY KEY          -- Stored logical identifier for one StepTransitions row.
);
ALTER TABLE step_transitions ADD COLUMN IF NOT EXISTS procedure_version TEXT;                       -- Procedure version whose control flow owns the transition.
ALTER TABLE step_transitions ADD COLUMN IF NOT EXISTS from_step TEXT;                               -- Source step; maps to pko:fromStep.
ALTER TABLE step_transitions ADD COLUMN IF NOT EXISTS to_step TEXT;                                 -- Destination step; maps to pko:toStep.
ALTER TABLE step_transitions ADD COLUMN IF NOT EXISTS transition_kind TEXT;                         -- Next, Alternative, or Fallback.
ALTER TABLE step_transitions ADD COLUMN IF NOT EXISTS condition TEXT;                               -- Condition under which the edge is taken.
ALTER TABLE step_transitions ADD COLUMN IF NOT EXISTS priority INTEGER;                             -- Evaluation priority when several outgoing edges exist.
ALTER TABLE step_transitions ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                       -- Exact PKO class IRI.
COMMENT ON TABLE step_transitions IS 'Directed control-flow edges represented as first-class pko:Transition instances with fromStep/toStep and next/alternative/fallback semantics.';
COMMENT ON COLUMN step_transitions.step_transition_id IS 'Stored logical identifier for one StepTransitions row.';
COMMENT ON COLUMN step_transitions.procedure_version IS 'Procedure version whose control flow owns the transition.';
COMMENT ON COLUMN step_transitions.from_step IS 'Source step; maps to pko:fromStep.';
COMMENT ON COLUMN step_transitions.to_step IS 'Destination step; maps to pko:toStep.';
COMMENT ON COLUMN step_transitions.transition_kind IS 'Next, Alternative, or Fallback.';
COMMENT ON COLUMN step_transitions.condition IS 'Condition under which the edge is taken.';
COMMENT ON COLUMN step_transitions.priority IS 'Evaluation priority when several outgoing edges exist.';
COMMENT ON COLUMN step_transitions.semantic_type_iri IS 'Exact PKO class IRI.';

