-- ----------------------------------------------------------------------------
-- KnowledgeFragments: Explicit records of tacit, implicit, explicit, and situated procedural knowledge. This is an ERB-PKO extension represented as provenance-bearing dcat:Resource instances.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS knowledge_fragments (
  knowledge_fragment_id               TEXT                 PRIMARY KEY          -- Stored logical identifier for one KnowledgeFragments row.
);
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS procedure_version TEXT;                    -- Procedure version informed by the fragment.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS step TEXT;                                 -- Optional step to which the fragment applies.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS knowledge_form TEXT;                       -- Tacit, Implicit, Explicit, SituatedJudgment, LessonLearned, or another declared form.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS statement TEXT;                            -- Captured knowledge statement.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS elicitation_session TEXT;                  -- Optional elicitation session that produced the fragment.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS source_agent TEXT;                         -- Practitioner or source agent.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS confidence TEXT;                           -- Low, Medium, or High confidence.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS valid_from TIMESTAMPTZ;                    -- Start of the fragment's valid-time interval.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS valid_to TIMESTAMPTZ;                      -- End of the fragment's valid-time interval.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS status TEXT;                               -- Draft, Reviewed, Approved, Rejected, or Superseded.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS owner_role TEXT;                           -- Role accountable for maintaining the fragment.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                   -- The evaluation context this row's time-dependent witnesses are judged under.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS last_reviewed_at TIMESTAMPTZ;              -- When this fragment was last actually reviewed and reaffirmed by its owning role. Null when it has never been reviewed since authoring. IsOverdueForReview infers recency from ValidFrom, which records when the claim became TRUE, not when anyone last looked at it. Those are different events, and the inference is deliberately left in place under its own name rather than silently rewritten to fall back on this column.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                    -- Extension class IRI.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS cognitive_basis TEXT;                      -- Intuition, PatternRecognition or Judgment for tacit knowledge; Articulated for knowledge stated outright.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS tacitness_degree INTEGER;                  -- Position on the tacit-to-explicit spectrum: 1 fully articulated to 5 not articulable.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS lost_in_translation TEXT;                  -- What the explicit statement fails to carry of the practice it was drawn from.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS encoded_as TEXT;                           -- HardRule, ConditionedGuidance, CueNarrative or Statement.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS stated_conditions TEXT;                    -- The conditions under which the fragment holds, as captured.
