-- ----------------------------------------------------------------------------
-- KnowledgeGaps: Known unknowns and missing procedural coverage. Explicit ERB-PKO extension used to govern scope and prevent silent incompleteness.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS knowledge_gaps (
  knowledge_gap_id                    TEXT                 PRIMARY KEY          -- Stored logical identifier for one KnowledgeGaps row.
);
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS procedure_version TEXT;                         -- Affected procedure version.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS step TEXT;                                      -- Affected step.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS statement TEXT;                                 -- What is not yet known or represented.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS severity TEXT;                                  -- Low, Medium, High, or Critical.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS blocking_kind TEXT;                             -- Blocking or NonBlocking.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS status TEXT;                                    -- Open, Investigating, Resolved, AcceptedRisk, or Closed.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS owner_role TEXT;                                -- Role responsible for resolving the gap.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS identified_at TIMESTAMPTZ;                      -- Time the gap was identified.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS resolution_plan TEXT;                           -- Resolution plan or final resolution.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                        -- The evaluation context this row's time-dependent witnesses are judged under.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                         -- Extension class IRI.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS gap_cause TEXT;                                 -- Gatekeeping, Sabotage, Undocumented or Unknown; blank when never classified.
