COMMENT ON COLUMN knowledge_gaps.identified_at IS 'Time the gap was identified.';
COMMENT ON COLUMN knowledge_gaps.resolution_plan IS 'Resolution plan or final resolution.';
COMMENT ON COLUMN knowledge_gaps.evaluation_context IS 'The evaluation context this row''s time-dependent witnesses are judged under.';
COMMENT ON COLUMN knowledge_gaps.semantic_type_iri IS 'Extension class IRI.';
COMMENT ON COLUMN knowledge_gaps.gap_cause IS 'Gatekeeping, Sabotage, Undocumented or Unknown; blank when never classified.';
