COMMENT ON COLUMN procedure_executions.shift IS 'Day or Night, where the work runs in shifts.';
COMMENT ON COLUMN procedure_executions.executed_on_machine IS 'Machine the procedure was executed on (pko-ind:isExecutedOnMachine).';
