-- ----------------------------------------------------------------------------
-- MessageTemplates: Approved channel templates projected from the canonical rulebook without becoming a second source of policy meaning.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS message_templates (
  message_template_id                 TEXT                 PRIMARY KEY          -- Stored logical identifier for one MessageTemplates row.
);
ALTER TABLE message_templates ADD COLUMN IF NOT EXISTS communication_policy TEXT;                   -- Channel policy governing the template.
ALTER TABLE message_templates ADD COLUMN IF NOT EXISTS resource TEXT;                               -- Template resource.
