ALTER TABLE semantic_mappings ADD COLUMN IF NOT EXISTS notes TEXT;                                  -- Mapping semantics and boundaries.
ALTER TABLE semantic_mappings ADD COLUMN IF NOT EXISTS available_standard_iri TEXT;                 -- A term in a reused standard that already means what this extension term means.
COMMENT ON TABLE semantic_mappings IS 'Machine-readable alignment from ERB table/field paths to exact PKO or reused ontology terms. Extension mappings are never presented as native PKO.';
