COMMENT ON COLUMN rulebook_fields.measured_distinct_value_count IS 'Distinct values of this field''s vw_* column, with blank counted as one value, measured in Postgres.';
COMMENT ON COLUMN rulebook_fields.semantic_type_iri IS 'Extension class IRI.';

