COMMENT ON COLUMN test_suites.label IS 'Display name for this suite.';
COMMENT ON COLUMN test_suites.semantic_type_iri IS 'Extension class IRI.';

-- ----------------------------------------------------------------------------
-- TestCases: The conformance suite, as data. One row per check, naming what it checks and — where applicable — the role question whose answer it defends. tools/run_test_suite.py executes these rows and writes the outcome back; it invents no checks of its own.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_cases (
  test_case_id                        TEXT                 PRIMARY KEY          -- Stored logical identifier for one TestCases row.
);
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS test_kind TEXT;                                     -- What class of check this is. One of: structural (the rulebook's own shape), formula-translates (the transpiler emitted a real function, not a NULL stub), view-loads (the view exists and is queryable), fk-resolves (every FK value names a real row), witness-discriminates (a boolean witness can distinguish cases in this data), witness-fires (a specific witness reads TRUE on at least one row), provenance (every invented field traces to a question), catalog-sync (RulebookFields matches the real schemas), question-answered (a role question has at least one predicate answering it), invariant (a domain rule that must hold), remediation (a seeded violation was resolved in model rather than deleted).
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS subject TEXT;                                       -- What is under test — a Table.Field, a table, a view, or a question id.
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS target_table TEXT;                                  -- The table this check reads, when it reads one.
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS target_field TEXT;                                  -- The field this check reads, when it reads one.
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS assertion TEXT;                                     -- What must be true, stated so a human can judge the verdict without reading code.
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS defends_question TEXT;                              -- The role question whose answer this check protects. Null for checks that defend the model's structure rather than a specific question.
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS suite TEXT;                                         -- The suite this check belongs to.
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS severity TEXT;                                      -- blocking — a failure means the model is stating something false; advisory — a failure means the model cannot state something it should be able to. Vacuity is advisory by design: a witness that cannot fire on this seed is not necessarily wrong, and forcing it red would create pressure to fabricate data.
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS last_outcome TEXT;                                  -- PASS, WARN, FAIL, or SKIP from the most recent run. Written by tools/run_test_suite.py from the substrate — never hand-edited.
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS last_detail TEXT;                                   -- The observed reading behind LastOutcome, e.g. a fire count or the error text.
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS last_run_at TIMESTAMPTZ;                            -- When this check last ran.
ALTER TABLE test_cases ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                             -- Extension class IRI.
COMMENT ON TABLE test_cases IS 'The conformance suite, as data. One row per check, naming what it checks and — where applicable — the role question whose answer it defends. tools/run_test_suite.py executes these rows and writes the outcome back; it invents no checks of its own.';
COMMENT ON COLUMN test_cases.test_case_id IS 'Stored logical identifier for one TestCases row.';
COMMENT ON COLUMN test_cases.test_kind IS 'What class of check this is. One of: structural (the rulebook''s own shape), formula-translates (the transpiler emitted a real function, not a NULL stub), view-loads (the view exists and is queryable), fk-resolves (every FK value names a real row), witness-discriminates (a boolean witness can distinguish cases in this data), witness-fires (a specific witness reads TRUE on at least one row), provenance (every invented field traces to a question), catalog-sync (RulebookFields matches the real schemas), question-answered (a role question has at least one predicate answering it), invariant (a domain rule that must hold), remediation (a seeded violation was resolved in model rather than deleted).';
COMMENT ON COLUMN test_cases.subject IS 'What is under test — a Table.Field, a table, a view, or a question id.';
COMMENT ON COLUMN test_cases.target_table IS 'The table this check reads, when it reads one.';
COMMENT ON COLUMN test_cases.target_field IS 'The field this check reads, when it reads one.';
COMMENT ON COLUMN test_cases.assertion IS 'What must be true, stated so a human can judge the verdict without reading code.';
COMMENT ON COLUMN test_cases.defends_question IS 'The role question whose answer this check protects. Null for checks that defend the model''s structure rather than a specific question.';
COMMENT ON COLUMN test_cases.suite IS 'The suite this check belongs to.';
COMMENT ON COLUMN test_cases.severity IS 'blocking — a failure means the model is stating something false; advisory — a failure means the model cannot state something it should be able to. Vacuity is advisory by design: a witness that cannot fire on this seed is not necessarily wrong, and forcing it red would create pressure to fabricate data.';
COMMENT ON COLUMN test_cases.last_outcome IS 'PASS, WARN, FAIL, or SKIP from the most recent run. Written by tools/run_test_suite.py from the substrate — never hand-edited.';
COMMENT ON COLUMN test_cases.last_detail IS 'The observed reading behind LastOutcome, e.g. a fire count or the error text.';
COMMENT ON COLUMN test_cases.last_run_at IS 'When this check last ran.';
COMMENT ON COLUMN test_cases.semantic_type_iri IS 'Extension class IRI.';

