-- ----------------------------------------------------------------------------
-- AppRoleProfiles: One row per role, carrying how that role is presented: its accent colour, its 128x128 icon, and the login-card copy. Presentation is data, so the app never hardcodes a colour or a label per role.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS app_role_profiles (
  app_role_profile_id                 TEXT                 PRIMARY KEY          -- Stored logical identifier for one AppRoleProfiles row.
);
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS role TEXT;                                   -- The role this presentation profile describes.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS display_label TEXT;                          -- Label shown on the login card and in the app chrome.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS role_kind TEXT;                              -- human or software. Drives the login-card silhouette and the icon plate shape.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS accent_color TEXT;                           -- Hex accent colour. Distinctive per role; used for chrome, the left-nav active state, and the icon plate.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS icon_mark TEXT;                              -- Name of the geometric mark drawn on this role's icon. Colour is never the only signal — the mark discriminates in greyscale.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS icon_png_base64 TEXT;                        -- 128x128 PNG icon for this role, base64-encoded, no data: prefix. Rendered on the login card and beside the role name throughout the app.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS pitch TEXT;                                  -- One line of login-card copy: what this role opens the app to do, in that role's own terms.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS sort_order NUMERIC;                          -- Display order on the login screen. Human roles first, then software roles.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                      -- Semantic type IRI for this row. An extension: PKO does not model application presentation.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS device TEXT;                                 -- The device this role's experience is designed for: phone or tablet.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS home_route TEXT;                             -- The route this role lands on after signing in.
ALTER TABLE app_role_profiles ADD COLUMN IF NOT EXISTS home_title TEXT;                             -- The title of that home page, as the role would say it.
COMMENT ON TABLE app_role_profiles IS 'One row per role, carrying how that role is presented: its accent colour, its 128x128 icon, and the login-card copy. Presentation is data, so the app never hardcodes a colour or a label per role.';
