COMMENT ON COLUMN app_role_profiles.icon_png_base64 IS '128x128 PNG icon for this role, base64-encoded, no data: prefix. Rendered on the login card and beside the role name throughout the app.';
COMMENT ON COLUMN app_role_profiles.pitch IS 'One line of login-card copy: what this role opens the app to do, in that role''s own terms.';
COMMENT ON COLUMN app_role_profiles.sort_order IS 'Display order on the login screen. Human roles first, then software roles.';
COMMENT ON COLUMN app_role_profiles.semantic_type_iri IS 'Semantic type IRI for this row. An extension: PKO does not model application presentation.';
COMMENT ON COLUMN app_role_profiles.device IS 'The device this role''s experience is designed for: phone or tablet.';
COMMENT ON COLUMN app_role_profiles.home_route IS 'The route this role lands on after signing in.';
