-- ----------------------------------------------------------------------------
-- AppNavGroups: The left-navigation section headers. A route names the group it appears under; the nav renders the groups its active role actually uses.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS app_nav_groups (
  app_nav_group_id                    TEXT                 PRIMARY KEY          -- Stored logical identifier for one AppNavGroups row.
);
ALTER TABLE app_nav_groups ADD COLUMN IF NOT EXISTS group_label TEXT;                               -- Section header text rendered in the left navigation.
ALTER TABLE app_nav_groups ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                         -- Semantic type IRI for this row. An extension: PKO does not model navigation.
COMMENT ON TABLE app_nav_groups IS 'The left-navigation section headers. A route names the group it appears under; the nav renders the groups its active role actually uses.';
