COMMENT ON COLUMN app_nav_groups.group_label IS 'Section header text rendered in the left navigation.';
COMMENT ON COLUMN app_nav_groups.semantic_type_iri IS 'Semantic type IRI for this row. An extension: PKO does not model navigation.';

-- ----------------------------------------------------------------------------
-- AppRoutes: One row per screen in the role-navigated application, as /{role}/{dashboard}/{entity...}. Each carries its purpose in the owning role's voice and brief layout hints, so a later build session has the brief without re-deriving it. Shared detail routes have no owning role.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS app_routes (
  app_route_id                        TEXT                 PRIMARY KEY          -- Stored logical identifier for one AppRoutes row.
);
ALTER TABLE app_routes ADD COLUMN IF NOT EXISTS route_path TEXT;                                    -- The URL path, /{role}/{dashboard}/{entity...}. Shared detail routes live under /shared/ because the same entity serves every role.
ALTER TABLE app_routes ADD COLUMN IF NOT EXISTS route_name TEXT;                                    -- Short label. This is the left-nav text.
ALTER TABLE app_routes ADD COLUMN IF NOT EXISTS surface TEXT;                                       -- domain | maintainer. Domain routes belong to the twelve accountable Roles. Maintainer routes are the model's own instrumentation (Admin, Explorer) and deliberately have no owning role — 'admin' is not a role anyone is accountable in.
ALTER TABLE app_routes ADD COLUMN IF NOT EXISTS owning_role TEXT;                                   -- The role whose navigation contains this route. Null for shared routes reachable from several roles.
ALTER TABLE app_routes ADD COLUMN IF NOT EXISTS nav_group TEXT;                                     -- Left-nav section this route appears under. Null for detail routes reached by drill-down rather than from the nav.
ALTER TABLE app_routes ADD COLUMN IF NOT EXISTS nav_order NUMERIC;                                  -- Sort order within the nav group.
ALTER TABLE app_routes ADD COLUMN IF NOT EXISTS route_kind TEXT;                                    -- dashboard | workspace | detail | index | action. Detail routes carry path parameters and are not in the nav.
ALTER TABLE app_routes ADD COLUMN IF NOT EXISTS purpose TEXT;                                       -- What the role does here, in that role's own voice. This is the brief for the build session.
ALTER TABLE app_routes ADD COLUMN IF NOT EXISTS layout_hints TEXT;                                  -- Brief layout direction: the shape of the screen, what leads, and what must not be collapsed or implied.
ALTER TABLE app_routes ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                             -- Semantic type IRI for this row. An extension: PKO models procedures, not the applications that display them.
COMMENT ON TABLE app_routes IS 'One row per screen in the role-navigated application, as /{role}/{dashboard}/{entity...}. Each carries its purpose in the owning role''s voice and brief layout hints, so a later build session has the brief without re-deriving it. Shared detail routes have no owning role.';
COMMENT ON COLUMN app_routes.app_route_id IS 'Stored logical identifier for one AppRoutes row.';
COMMENT ON COLUMN app_routes.route_path IS 'The URL path, /{role}/{dashboard}/{entity...}. Shared detail routes live under /shared/ because the same entity serves every role.';
COMMENT ON COLUMN app_routes.route_name IS 'Short label. This is the left-nav text.';
COMMENT ON COLUMN app_routes.surface IS 'domain | maintainer. Domain routes belong to the twelve accountable Roles. Maintainer routes are the model''s own instrumentation (Admin, Explorer) and deliberately have no owning role — ''admin'' is not a role anyone is accountable in.';
COMMENT ON COLUMN app_routes.owning_role IS 'The role whose navigation contains this route. Null for shared routes reachable from several roles.';
COMMENT ON COLUMN app_routes.nav_group IS 'Left-nav section this route appears under. Null for detail routes reached by drill-down rather than from the nav.';
COMMENT ON COLUMN app_routes.nav_order IS 'Sort order within the nav group.';
COMMENT ON COLUMN app_routes.route_kind IS 'dashboard | workspace | detail | index | action. Detail routes carry path parameters and are not in the nav.';
COMMENT ON COLUMN app_routes.purpose IS 'What the role does here, in that role''s own voice. This is the brief for the build session.';
COMMENT ON COLUMN app_routes.layout_hints IS 'Brief layout direction: the shape of the screen, what leads, and what must not be collapsed or implied.';
COMMENT ON COLUMN app_routes.semantic_type_iri IS 'Semantic type IRI for this row. An extension: PKO models procedures, not the applications that display them.';

-- ----------------------------------------------------------------------------
-- AppRouteQuestions: Junction: which RoleQuestions each route helps answer. Deliberately many-to-many — a question is answered across several routes and a route serves several questions. It is not, and should not become, 1:1.
