ALTER TABLE app_route_questions ADD COLUMN IF NOT EXISTS question TEXT;                             -- The role question this route helps answer.
ALTER TABLE app_route_questions ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                    -- Semantic type IRI for this row. An extension.
