-- ----------------------------------------------------------------------------
-- RulebookTables: Census of every table in this rulebook. The table-level counterpart to RulebookFields, and the anchor every access policy points at. Derived by tools/reconcile_field_catalog.py -- never hand-maintained.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS rulebook_tables (
  rulebook_table_id                   TEXT                 PRIMARY KEY          -- Primary key: the rulebook table name, verbatim. rulebook-to-postgres synthesizes a lowercased slug PK for a table with no <Entity>Id and rewrites every FK to it, which broke each formula comparing an FK to TableName.
);
ALTER TABLE rulebook_tables ADD COLUMN IF NOT EXISTS table_name TEXT;                               -- Stored logical identifier: the rulebook table name, e.g. 'Procedures'.
ALTER TABLE rulebook_tables ADD COLUMN IF NOT EXISTS physical_table TEXT;                           -- snake_case Postgres base table name emitted by rulebook-to-postgres.
ALTER TABLE rulebook_tables ADD COLUMN IF NOT EXISTS physical_view TEXT;                            -- snake_case Postgres view name (vw_*) carrying the computed columns.
ALTER TABLE rulebook_tables ADD COLUMN IF NOT EXISTS subject_area TEXT;                             -- Coarse grouping used to organise role schemas, e.g. 'execution', 'governance'.
ALTER TABLE rulebook_tables ADD COLUMN IF NOT EXISTS is_extension BOOLEAN;                          -- True when this table is an ERB extension rather than a native/aligned PKO term.
ALTER TABLE rulebook_tables ADD COLUMN IF NOT EXISTS measured_row_count INTEGER;                    -- Rows in this table's vw_* view, measured in Postgres by tools/measure_catalog.py.
ALTER TABLE rulebook_tables ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                        -- Semantic type IRI.
ALTER TABLE rulebook_tables ADD COLUMN IF NOT EXISTS organization_level TEXT;                       -- Conceptual (what kinds of thing exist), Structural (how instances are arranged) or Contextual (where knowledge applies).
COMMENT ON TABLE rulebook_tables IS 'Census of every table in this rulebook. The table-level counterpart to RulebookFields, and the anchor every access policy points at. Derived by tools/reconcile_field_catalog.py -- never hand-maintained.';
COMMENT ON COLUMN rulebook_tables.rulebook_table_id IS 'Primary key: the rulebook table name, verbatim. rulebook-to-postgres synthesizes a lowercased slug PK for a table with no <Entity>Id and rewrites every FK to it, which broke each formula comparing an FK to TableName.';
COMMENT ON COLUMN rulebook_tables.table_name IS 'Stored logical identifier: the rulebook table name, e.g. ''Procedures''.';
COMMENT ON COLUMN rulebook_tables.physical_table IS 'snake_case Postgres base table name emitted by rulebook-to-postgres.';
COMMENT ON COLUMN rulebook_tables.physical_view IS 'snake_case Postgres view name (vw_*) carrying the computed columns.';
COMMENT ON COLUMN rulebook_tables.subject_area IS 'Coarse grouping used to organise role schemas, e.g. ''execution'', ''governance''.';
COMMENT ON COLUMN rulebook_tables.is_extension IS 'True when this table is an ERB extension rather than a native/aligned PKO term.';
COMMENT ON COLUMN rulebook_tables.measured_row_count IS 'Rows in this table''s vw_* view, measured in Postgres by tools/measure_catalog.py.';
COMMENT ON COLUMN rulebook_tables.semantic_type_iri IS 'Semantic type IRI.';
COMMENT ON COLUMN rulebook_tables.organization_level IS 'Conceptual (what kinds of thing exist), Structural (how instances are arranged) or Contextual (where knowledge applies).';

-- ----------------------------------------------------------------------------
-- AccessPrincipals: Security principals -- the identities policies attach to. A principal is the console persona a person logs in as; it maps many-to-one onto a domain Role, so 'who may see this row' is expressed once against the domain vocabulary while the UI keeps its own persona names. Each principal owns exactly one Postgres role and one Postgres schema.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS access_principals (
  access_principal_id                 TEXT                 PRIMARY KEY          -- Stored logical identifier, e.g. 'principal-controller'.
);
ALTER TABLE access_principals ADD COLUMN IF NOT EXISTS label TEXT;                                  -- Display label shown in the console role picker.
ALTER TABLE access_principals ADD COLUMN IF NOT EXISTS domain_role TEXT;                            -- Domain role whose authority this principal exercises.
ALTER TABLE access_principals ADD COLUMN IF NOT EXISTS pg_role_name TEXT;                           -- Postgres role name this principal authenticates as, e.g. 'pko_controller'.
ALTER TABLE access_principals ADD COLUMN IF NOT EXISTS schema_name TEXT;                            -- Postgres schema that is this principal's entire visible world, e.g. 'pko_controller'.
ALTER TABLE access_principals ADD COLUMN IF NOT EXISTS is_administrator BOOLEAN;                    -- True when this principal may read every table and edit access policy.
ALTER TABLE access_principals ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                      -- Semantic type IRI.
COMMENT ON TABLE access_principals IS 'Security principals -- the identities policies attach to. A principal is the console persona a person logs in as; it maps many-to-one onto a domain Role, so ''who may see this row'' is expressed once against the domain vocabulary while the UI keeps its own persona names. Each principal owns exactly one Postgres role and one Postgres schema.';
COMMENT ON COLUMN access_principals.access_principal_id IS 'Stored logical identifier, e.g. ''principal-controller''.';
COMMENT ON COLUMN access_principals.label IS 'Display label shown in the console role picker.';
COMMENT ON COLUMN access_principals.domain_role IS 'Domain role whose authority this principal exercises.';
COMMENT ON COLUMN access_principals.pg_role_name IS 'Postgres role name this principal authenticates as, e.g. ''pko_controller''.';
COMMENT ON COLUMN access_principals.schema_name IS 'Postgres schema that is this principal''s entire visible world, e.g. ''pko_controller''.';
COMMENT ON COLUMN access_principals.is_administrator IS 'True when this principal may read every table and edit access policy.';
COMMENT ON COLUMN access_principals.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- AccessPolicies: Row-level security policies: the VERTICAL cut. One row per principal x table x command, carrying the predicate that decides which rows are visible. RowPredicate is emitted verbatim into a Postgres USING clause, so it may call any SECURITY DEFINER calc_* function and therefore reference inference fields many hops down the DAG.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS access_policies (
  access_policy_id                    TEXT                 PRIMARY KEY          -- Stored logical identifier, e.g. 'pol-controller-procedures-select'.
);
ALTER TABLE access_policies ADD COLUMN IF NOT EXISTS principal TEXT;                                -- Principal this policy grants to.
ALTER TABLE access_policies ADD COLUMN IF NOT EXISTS target_table TEXT;                             -- Rulebook table this policy guards.
ALTER TABLE access_policies ADD COLUMN IF NOT EXISTS command TEXT;                                  -- SQL command the policy governs: SELECT, INSERT, UPDATE, DELETE or ALL.
ALTER TABLE access_policies ADD COLUMN IF NOT EXISTS row_predicate TEXT;                            -- SQL boolean expression emitted into USING(...). Empty means all rows of the table. Must not sub-select the guarded table -- Postgres raises infinite recursion; route such predicates through a SECURITY DEFINER function instead.
ALTER TABLE access_policies ADD COLUMN IF NOT EXISTS check_predicate TEXT;                          -- SQL boolean expression emitted into WITH CHECK(...) for write commands. Empty reuses RowPredicate.
ALTER TABLE access_policies ADD COLUMN IF NOT EXISTS rationale TEXT;                                -- Why this principal is entitled to these rows, in the granting authority's words.
ALTER TABLE access_policies ADD COLUMN IF NOT EXISTS references_inference BOOLEAN;                  -- True when RowPredicate calls a calc_* function, i.e. the cut depends on a derived field rather than a stored column.
ALTER TABLE access_policies ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                        -- Semantic type IRI.
COMMENT ON TABLE access_policies IS 'Row-level security policies: the VERTICAL cut. One row per principal x table x command, carrying the predicate that decides which rows are visible. RowPredicate is emitted verbatim into a Postgres USING clause, so it may call any SECURITY DEFINER calc_* function and therefore reference inference fields many hops down the DAG.';
COMMENT ON COLUMN access_policies.access_policy_id IS 'Stored logical identifier, e.g. ''pol-controller-procedures-select''.';
COMMENT ON COLUMN access_policies.principal IS 'Principal this policy grants to.';
COMMENT ON COLUMN access_policies.target_table IS 'Rulebook table this policy guards.';
COMMENT ON COLUMN access_policies.command IS 'SQL command the policy governs: SELECT, INSERT, UPDATE, DELETE or ALL.';
COMMENT ON COLUMN access_policies.row_predicate IS 'SQL boolean expression emitted into USING(...). Empty means all rows of the table. Must not sub-select the guarded table -- Postgres raises infinite recursion; route such predicates through a SECURITY DEFINER function instead.';
COMMENT ON COLUMN access_policies.check_predicate IS 'SQL boolean expression emitted into WITH CHECK(...) for write commands. Empty reuses RowPredicate.';
COMMENT ON COLUMN access_policies.rationale IS 'Why this principal is entitled to these rows, in the granting authority''s words.';
COMMENT ON COLUMN access_policies.references_inference IS 'True when RowPredicate calls a calc_* function, i.e. the cut depends on a derived field rather than a stored column.';
COMMENT ON COLUMN access_policies.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- FieldGrants: Field-level grants: the HORIZONTAL cut. One row per principal x field. A field with no grant row is not filtered from the principal's view -- it is absent from it, so the column does not exist as far as that principal's SQL is concerned.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS field_grants (
  field_grant_id                      TEXT                 PRIMARY KEY          -- Stored logical identifier, e.g. 'fg-controller-Procedures.Title'.
);
ALTER TABLE field_grants ADD COLUMN IF NOT EXISTS principal TEXT;                                   -- Principal receiving the grant.
ALTER TABLE field_grants ADD COLUMN IF NOT EXISTS target_field TEXT;                                -- Catalogued field being exposed.
ALTER TABLE field_grants ADD COLUMN IF NOT EXISTS can_read BOOLEAN;                                 -- True when the principal may read this field.
ALTER TABLE field_grants ADD COLUMN IF NOT EXISTS can_write BOOLEAN;                                -- True when the principal may write this field.
ALTER TABLE field_grants ADD COLUMN IF NOT EXISTS mask_strategy TEXT;                               -- How the value is presented when read: 'plain', 'redacted' or 'hashed'.
ALTER TABLE field_grants ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                           -- Semantic type IRI.
COMMENT ON TABLE field_grants IS 'Field-level grants: the HORIZONTAL cut. One row per principal x field. A field with no grant row is not filtered from the principal''s view -- it is absent from it, so the column does not exist as far as that principal''s SQL is concerned.';
COMMENT ON COLUMN field_grants.field_grant_id IS 'Stored logical identifier, e.g. ''fg-controller-Procedures.Title''.';
COMMENT ON COLUMN field_grants.principal IS 'Principal receiving the grant.';
COMMENT ON COLUMN field_grants.target_field IS 'Catalogued field being exposed.';
COMMENT ON COLUMN field_grants.can_read IS 'True when the principal may read this field.';
COMMENT ON COLUMN field_grants.can_write IS 'True when the principal may write this field.';
COMMENT ON COLUMN field_grants.mask_strategy IS 'How the value is presented when read: ''plain'', ''redacted'' or ''hashed''.';
COMMENT ON COLUMN field_grants.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- RoleSchemas: One Postgres schema per principal -- the principal's entire visible world. The schema is the only entry on that principal's search_path, so a table absent from it cannot be named at all.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS role_schemas (
  role_schema_id                      TEXT                 PRIMARY KEY          -- Stored logical identifier, e.g. 'schema-controller'.
);
ALTER TABLE role_schemas ADD COLUMN IF NOT EXISTS principal TEXT;                                   -- Principal that owns this schema.
ALTER TABLE role_schemas ADD COLUMN IF NOT EXISTS schema_name TEXT;                                 -- Postgres schema name, e.g. 'pko_controller'.
ALTER TABLE role_schemas ADD COLUMN IF NOT EXISTS is_sealed BOOLEAN;                                -- True when the principal may not create objects in its own schema.
ALTER TABLE role_schemas ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                           -- Semantic type IRI.
COMMENT ON TABLE role_schemas IS 'One Postgres schema per principal -- the principal''s entire visible world. The schema is the only entry on that principal''s search_path, so a table absent from it cannot be named at all.';
COMMENT ON COLUMN role_schemas.role_schema_id IS 'Stored logical identifier, e.g. ''schema-controller''.';
COMMENT ON COLUMN role_schemas.principal IS 'Principal that owns this schema.';
COMMENT ON COLUMN role_schemas.schema_name IS 'Postgres schema name, e.g. ''pko_controller''.';
COMMENT ON COLUMN role_schemas.is_sealed IS 'True when the principal may not create objects in its own schema.';
COMMENT ON COLUMN role_schemas.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- RoleSchemaViews: The emitted views: one per principal x table. ColumnList is DERIVED from FieldGrants, so toggling a single grant changes the emitted DDL with no second edit anywhere. This is what makes an admin's save reshape the database without touching UI code.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS role_schema_views (
  role_schema_view_id                 TEXT                 PRIMARY KEY          -- Stored logical identifier, e.g. 'rsv-controller-procedures'.
);
ALTER TABLE role_schema_views ADD COLUMN IF NOT EXISTS role_schema TEXT;                            -- Schema this view is emitted into.
ALTER TABLE role_schema_views ADD COLUMN IF NOT EXISTS principal TEXT;                              -- Principal that will read this view.
ALTER TABLE role_schema_views ADD COLUMN IF NOT EXISTS target_table TEXT;                           -- Rulebook table this view exposes.
ALTER TABLE role_schema_views ADD COLUMN IF NOT EXISTS view_name TEXT;                              -- Unqualified view name inside the principal's schema, e.g. 'procedures'.
ALTER TABLE role_schema_views ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                      -- Semantic type IRI.
COMMENT ON TABLE role_schema_views IS 'The emitted views: one per principal x table. ColumnList is DERIVED from FieldGrants, so toggling a single grant changes the emitted DDL with no second edit anywhere. This is what makes an admin''s save reshape the database without touching UI code.';
COMMENT ON COLUMN role_schema_views.role_schema_view_id IS 'Stored logical identifier, e.g. ''rsv-controller-procedures''.';
COMMENT ON COLUMN role_schema_views.role_schema IS 'Schema this view is emitted into.';
COMMENT ON COLUMN role_schema_views.principal IS 'Principal that will read this view.';
COMMENT ON COLUMN role_schema_views.target_table IS 'Rulebook table this view exposes.';
COMMENT ON COLUMN role_schema_views.view_name IS 'Unqualified view name inside the principal''s schema, e.g. ''procedures''.';
COMMENT ON COLUMN role_schema_views.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- JwtClaimMappings: Maps verified JWT claims onto the SQL accessors row predicates call. Magic-links is the notary: it asserts only that the bearer controls an email address. This table records how that verified email, and any additional claims, become values a policy can test.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS jwt_claim_mappings (
  jwt_claim_mapping_id                TEXT                 PRIMARY KEY          -- Stored logical identifier, e.g. 'claim-email'.
);
ALTER TABLE jwt_claim_mappings ADD COLUMN IF NOT EXISTS claim_name TEXT;                            -- Claim key as it appears in the verified JWT payload, e.g. 'email'.
ALTER TABLE jwt_claim_mappings ADD COLUMN IF NOT EXISTS sql_accessor TEXT;                          -- SQL function a policy calls to read the claim, e.g. 'app.jwt_email()'.
ALTER TABLE jwt_claim_mappings ADD COLUMN IF NOT EXISTS is_reserved_claim BOOLEAN;                  -- True for claims magic-links controls and an app cannot override: email, iss, iat, nbf, exp, sub, tenant_id.
ALTER TABLE jwt_claim_mappings ADD COLUMN IF NOT EXISTS maps_to_principal BOOLEAN;                  -- True when this claim is what resolves the caller to an AccessPrincipals row.
ALTER TABLE jwt_claim_mappings ADD COLUMN IF NOT EXISTS description2 TEXT;                          -- What the claim asserts and who vouches for it.
ALTER TABLE jwt_claim_mappings ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                     -- Semantic type IRI.
COMMENT ON TABLE jwt_claim_mappings IS 'Maps verified JWT claims onto the SQL accessors row predicates call. Magic-links is the notary: it asserts only that the bearer controls an email address. This table records how that verified email, and any additional claims, become values a policy can test.';
COMMENT ON COLUMN jwt_claim_mappings.jwt_claim_mapping_id IS 'Stored logical identifier, e.g. ''claim-email''.';
COMMENT ON COLUMN jwt_claim_mappings.claim_name IS 'Claim key as it appears in the verified JWT payload, e.g. ''email''.';
COMMENT ON COLUMN jwt_claim_mappings.sql_accessor IS 'SQL function a policy calls to read the claim, e.g. ''app.jwt_email()''.';
COMMENT ON COLUMN jwt_claim_mappings.is_reserved_claim IS 'True for claims magic-links controls and an app cannot override: email, iss, iat, nbf, exp, sub, tenant_id.';
COMMENT ON COLUMN jwt_claim_mappings.maps_to_principal IS 'True when this claim is what resolves the caller to an AccessPrincipals row.';
COMMENT ON COLUMN jwt_claim_mappings.description2 IS 'What the claim asserts and who vouches for it.';
COMMENT ON COLUMN jwt_claim_mappings.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- AccessDenialTests: Denial witnesses. A policy with no failing case seeded against it is an assertion, not evidence -- the same acceptance bar the rest of this rulebook holds. Each row names a principal, a query, and the row that MUST NOT come back, so a policy that silently stops enforcing is caught by a red test rather than by an incident.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS access_denial_tests (
  access_denial_test_id               TEXT                 PRIMARY KEY          -- Stored logical identifier, e.g. 'deny-analyst-other-org-procedures'.
);
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS target_policy TEXT;                        -- Policy this test exercises.
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS principal TEXT;                            -- Principal the query runs as.
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS target_table TEXT;                         -- Table queried.
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS forbidden_row_id TEXT;                     -- Primary key of the row that must be invisible to this principal.
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS expected_visible BOOLEAN;                  -- False for a denial test: the row must not appear. True asserts a row the principal is entitled to does appear.
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS observed_visible BOOLEAN;                  -- What the substrate actually returned on the last run. Written back by the verifier, never hand-set.
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS last_run_at TIMESTAMPTZ;                   -- When this test was last executed against Postgres.
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS rationale TEXT;                            -- Why this row must (or must not) be visible, and which predicate it exercises.
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS forbidden_table TEXT;                      -- For a table-absence witness: the table that must NOT exist in this principal's schema. Selecting it must raise 'relation does not exist', not return zero rows.
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS forbidden_column TEXT;                     -- For a column-absence witness: the column that must NOT exist in this principal's view. Selecting it must raise 'column does not exist', not return null.
ALTER TABLE access_denial_tests ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                    -- Semantic type IRI.
COMMENT ON TABLE access_denial_tests IS 'Denial witnesses. A policy with no failing case seeded against it is an assertion, not evidence -- the same acceptance bar the rest of this rulebook holds. Each row names a principal, a query, and the row that MUST NOT come back, so a policy that silently stops enforcing is caught by a red test rather than by an incident.';
COMMENT ON COLUMN access_denial_tests.access_denial_test_id IS 'Stored logical identifier, e.g. ''deny-analyst-other-org-procedures''.';
COMMENT ON COLUMN access_denial_tests.target_policy IS 'Policy this test exercises.';
COMMENT ON COLUMN access_denial_tests.principal IS 'Principal the query runs as.';
COMMENT ON COLUMN access_denial_tests.target_table IS 'Table queried.';
COMMENT ON COLUMN access_denial_tests.forbidden_row_id IS 'Primary key of the row that must be invisible to this principal.';
COMMENT ON COLUMN access_denial_tests.expected_visible IS 'False for a denial test: the row must not appear. True asserts a row the principal is entitled to does appear.';
COMMENT ON COLUMN access_denial_tests.observed_visible IS 'What the substrate actually returned on the last run. Written back by the verifier, never hand-set.';
COMMENT ON COLUMN access_denial_tests.last_run_at IS 'When this test was last executed against Postgres.';
COMMENT ON COLUMN access_denial_tests.rationale IS 'Why this row must (or must not) be visible, and which predicate it exercises.';
COMMENT ON COLUMN access_denial_tests.forbidden_table IS 'For a table-absence witness: the table that must NOT exist in this principal''s schema. Selecting it must raise ''relation does not exist'', not return zero rows.';
COMMENT ON COLUMN access_denial_tests.forbidden_column IS 'For a column-absence witness: the column that must NOT exist in this principal''s view. Selecting it must raise ''column does not exist'', not return null.';
COMMENT ON COLUMN access_denial_tests.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- AppUsers: Sign-in identities. One row per person or automation that can authenticate. EmailAddress is what a verified token asserts; everything else about the caller is resolved from here inside the database, never trusted from the token.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS app_users (
  app_user_id                         TEXT                 PRIMARY KEY          -- Stored logical identifier, e.g. 'user-maria-chen'.
);
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS email_address TEXT;                                  -- Verified email. The one claim magic-links vouches for, and the join key from a token back to this row.
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS display_name TEXT;                                   -- Name shown in the console.
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS linked_agent TEXT;                                   -- Domain agent this sign-in identity corresponds to.
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS is_enabled BOOLEAN;                                  -- False disables sign-in without deleting the identity or its history.
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                              -- Semantic type IRI.
COMMENT ON TABLE app_users IS 'Sign-in identities. One row per person or automation that can authenticate. EmailAddress is what a verified token asserts; everything else about the caller is resolved from here inside the database, never trusted from the token.';
COMMENT ON COLUMN app_users.app_user_id IS 'Stored logical identifier, e.g. ''user-maria-chen''.';
COMMENT ON COLUMN app_users.email_address IS 'Verified email. The one claim magic-links vouches for, and the join key from a token back to this row.';
COMMENT ON COLUMN app_users.display_name IS 'Name shown in the console.';
COMMENT ON COLUMN app_users.linked_agent IS 'Domain agent this sign-in identity corresponds to.';
COMMENT ON COLUMN app_users.is_enabled IS 'False disables sign-in without deleting the identity or its history.';
COMMENT ON COLUMN app_users.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- PrincipalAssignments: Which principals a user may act as. The authorization half of sign-in: a verified email proves who you are, this table decides what you may become. A user with two assignments picks one at sign-in, and the choice is verified here rather than accepted from the client.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS principal_assignments (
  principal_assignment_id             TEXT                 PRIMARY KEY          -- Stored logical identifier, e.g. 'pa-maria-finance-analyst'.
);
ALTER TABLE principal_assignments ADD COLUMN IF NOT EXISTS app_user TEXT;                           -- Sign-in identity being granted.
ALTER TABLE principal_assignments ADD COLUMN IF NOT EXISTS principal TEXT;                          -- Principal the user may act as.
ALTER TABLE principal_assignments ADD COLUMN IF NOT EXISTS is_default BOOLEAN;                      -- True for the principal selected when the user does not name one.
ALTER TABLE principal_assignments ADD COLUMN IF NOT EXISTS granted_rationale TEXT;                  -- Why this user may act as this principal.
ALTER TABLE principal_assignments ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                  -- Semantic type IRI.
COMMENT ON TABLE principal_assignments IS 'Which principals a user may act as. The authorization half of sign-in: a verified email proves who you are, this table decides what you may become. A user with two assignments picks one at sign-in, and the choice is verified here rather than accepted from the client.';
COMMENT ON COLUMN principal_assignments.principal_assignment_id IS 'Stored logical identifier, e.g. ''pa-maria-finance-analyst''.';
COMMENT ON COLUMN principal_assignments.app_user IS 'Sign-in identity being granted.';
COMMENT ON COLUMN principal_assignments.principal IS 'Principal the user may act as.';
COMMENT ON COLUMN principal_assignments.is_default IS 'True for the principal selected when the user does not name one.';
COMMENT ON COLUMN principal_assignments.granted_rationale IS 'Why this user may act as this principal.';
COMMENT ON COLUMN principal_assignments.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- IssuedTokens: Audit trail of every token minted. A token records which user signed in, which principal they chose, and the claims that were joined from the database at mint time -- so a later question of 'what could this session see' is answerable from data rather than reconstruction.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS issued_tokens (
  issued_token_id                     TEXT                 PRIMARY KEY          -- Stored logical identifier for one mint event.
);
ALTER TABLE issued_tokens ADD COLUMN IF NOT EXISTS app_user TEXT;                                   -- Identity that signed in.
ALTER TABLE issued_tokens ADD COLUMN IF NOT EXISTS principal TEXT;                                  -- Principal the token authorises.
ALTER TABLE issued_tokens ADD COLUMN IF NOT EXISTS issued_at TIMESTAMPTZ;                           -- When the token was minted.
ALTER TABLE issued_tokens ADD COLUMN IF NOT EXISTS expires_at TIMESTAMPTZ;                          -- When the token stops being accepted.
ALTER TABLE issued_tokens ADD COLUMN IF NOT EXISTS issuer TEXT;                                     -- Who minted it: 'dev-mint' locally, or the magic-links tenant URL in production.
ALTER TABLE issued_tokens ADD COLUMN IF NOT EXISTS subject_claim TEXT;                              -- The 'sub' claim: the AppUserId the bearer is asserted to be.
ALTER TABLE issued_tokens ADD COLUMN IF NOT EXISTS claims_snapshot TEXT;                            -- JSON of the additional claims joined from the database at mint time.
ALTER TABLE issued_tokens ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                          -- Semantic type IRI.
COMMENT ON TABLE issued_tokens IS 'Audit trail of every token minted. A token records which user signed in, which principal they chose, and the claims that were joined from the database at mint time -- so a later question of ''what could this session see'' is answerable from data rather than reconstruction.';
COMMENT ON COLUMN issued_tokens.issued_token_id IS 'Stored logical identifier for one mint event.';
COMMENT ON COLUMN issued_tokens.app_user IS 'Identity that signed in.';
COMMENT ON COLUMN issued_tokens.principal IS 'Principal the token authorises.';
COMMENT ON COLUMN issued_tokens.issued_at IS 'When the token was minted.';
COMMENT ON COLUMN issued_tokens.expires_at IS 'When the token stops being accepted.';
COMMENT ON COLUMN issued_tokens.issuer IS 'Who minted it: ''dev-mint'' locally, or the magic-links tenant URL in production.';
COMMENT ON COLUMN issued_tokens.subject_claim IS 'The ''sub'' claim: the AppUserId the bearer is asserted to be.';
COMMENT ON COLUMN issued_tokens.claims_snapshot IS 'JSON of the additional claims joined from the database at mint time.';
COMMENT ON COLUMN issued_tokens.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- ProcessMiningRuns: One conformance-checking run of a mined event log against a documented procedure version — a third kind of evidence, distinct from an elicitation session (someone's account) or a knowledge fragment (a claim): what the system of record actually did, discovered by process mining rather than told to us.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS process_mining_runs (
  process_mining_run_id               TEXT                 PRIMARY KEY          -- Stored logical identifier for one ProcessMiningRuns row.
);
ALTER TABLE process_mining_runs ADD COLUMN IF NOT EXISTS procedure_version TEXT;                    -- Procedure version this mined event log is checked against.
ALTER TABLE process_mining_runs ADD COLUMN IF NOT EXISTS event_log_source TEXT;                     -- System or log the event log was extracted from (e.g. an ERP audit log).
ALTER TABLE process_mining_runs ADD COLUMN IF NOT EXISTS mined_at TIMESTAMPTZ;                      -- When this mining/conformance-checking run was performed.
ALTER TABLE process_mining_runs ADD COLUMN IF NOT EXISTS discovered_variant_count INTEGER;          -- Distinct process variants discovered in the mined event log.
ALTER TABLE process_mining_runs ADD COLUMN IF NOT EXISTS conforming_variant_count INTEGER;          -- How many of the discovered variants exactly match a documented path through StepTransitions.
ALTER TABLE process_mining_runs ADD COLUMN IF NOT EXISTS deviation_description TEXT;                -- Narrative of the most significant discovered deviation, if any.
ALTER TABLE process_mining_runs ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                   -- The evaluation context this row's time-dependent witnesses are judged under.
ALTER TABLE process_mining_runs ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                    -- Extension class IRI.
COMMENT ON TABLE process_mining_runs IS 'One conformance-checking run of a mined event log against a documented procedure version — a third kind of evidence, distinct from an elicitation session (someone''s account) or a knowledge fragment (a claim): what the system of record actually did, discovered by process mining rather than told to us.';
COMMENT ON COLUMN process_mining_runs.process_mining_run_id IS 'Stored logical identifier for one ProcessMiningRuns row.';
COMMENT ON COLUMN process_mining_runs.procedure_version IS 'Procedure version this mined event log is checked against.';
COMMENT ON COLUMN process_mining_runs.event_log_source IS 'System or log the event log was extracted from (e.g. an ERP audit log).';
COMMENT ON COLUMN process_mining_runs.mined_at IS 'When this mining/conformance-checking run was performed.';
COMMENT ON COLUMN process_mining_runs.discovered_variant_count IS 'Distinct process variants discovered in the mined event log.';
COMMENT ON COLUMN process_mining_runs.conforming_variant_count IS 'How many of the discovered variants exactly match a documented path through StepTransitions.';
COMMENT ON COLUMN process_mining_runs.deviation_description IS 'Narrative of the most significant discovered deviation, if any.';
COMMENT ON COLUMN process_mining_runs.evaluation_context IS 'The evaluation context this row''s time-dependent witnesses are judged under.';
COMMENT ON COLUMN process_mining_runs.semantic_type_iri IS 'Extension class IRI.';

-- ----------------------------------------------------------------------------
-- Vocabularies: A controlled vocabulary / SKOS-style concept scheme — one facet of standardized terminology (e.g. a family of control categories) that Requirements and other rows can point at instead of restating the concept in free text each time.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS vocabularies (
  vocabulary_id                       TEXT                 PRIMARY KEY          -- Stored logical identifier for one Vocabularies row.
);
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS title TEXT;                                       -- Human-facing name of this controlled vocabulary.
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS scheme_uri TEXT;                                  -- SKOS ConceptScheme IRI for this vocabulary.
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS governing_role TEXT;                              -- Role accountable for defining and maintaining terms in this vocabulary.
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                           -- Extension class IRI.
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS scheme_kind TEXT;                                 -- ControlledVocabulary, Taxonomy or Thesaurus.
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS model_layer TEXT;                                 -- VocabularyLayer for controlled concept schemes, kept apart from the ontology layer.
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS governed_dimension TEXT;                          -- What the scheme controls: Activity, Role, WorkflowStatus, ArtifactType, AgentCapability, ...
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS publication_format TEXT;                          -- How the scheme is published: SKOS Turtle, or a PDF glossary.
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS prefix TEXT;                                      -- Namespace prefix.
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS established_at TIMESTAMPTZ;                       -- When vocabulary control was established.
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS ontology_modeling_started_at TIMESTAMPTZ;         -- When ontology modeling for the same domain began.
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS governs_procedure TEXT;                           -- Procedure whose knowledge the scheme controls.
COMMENT ON TABLE vocabularies IS 'A controlled vocabulary / SKOS-style concept scheme — one facet of standardized terminology (e.g. a family of control categories) that Requirements and other rows can point at instead of restating the concept in free text each time.';
COMMENT ON COLUMN vocabularies.vocabulary_id IS 'Stored logical identifier for one Vocabularies row.';
COMMENT ON COLUMN vocabularies.title IS 'Human-facing name of this controlled vocabulary.';
COMMENT ON COLUMN vocabularies.scheme_uri IS 'SKOS ConceptScheme IRI for this vocabulary.';
COMMENT ON COLUMN vocabularies.governing_role IS 'Role accountable for defining and maintaining terms in this vocabulary.';
COMMENT ON COLUMN vocabularies.semantic_type_iri IS 'Extension class IRI.';
COMMENT ON COLUMN vocabularies.scheme_kind IS 'ControlledVocabulary, Taxonomy or Thesaurus.';
COMMENT ON COLUMN vocabularies.model_layer IS 'VocabularyLayer for controlled concept schemes, kept apart from the ontology layer.';
COMMENT ON COLUMN vocabularies.governed_dimension IS 'What the scheme controls: Activity, Role, WorkflowStatus, ArtifactType, AgentCapability, ...';
COMMENT ON COLUMN vocabularies.publication_format IS 'How the scheme is published: SKOS Turtle, or a PDF glossary.';
COMMENT ON COLUMN vocabularies.prefix IS 'Namespace prefix.';
COMMENT ON COLUMN vocabularies.established_at IS 'When vocabulary control was established.';
COMMENT ON COLUMN vocabularies.ontology_modeling_started_at IS 'When ontology modeling for the same domain began.';
COMMENT ON COLUMN vocabularies.governs_procedure IS 'Procedure whose knowledge the scheme controls.';

-- ----------------------------------------------------------------------------
-- VocabularyTerms: One controlled, defined term (a SKOS Concept) within a Vocabulary. Requirements point at a VocabularyTerm instead of free-texting the same concept in a new Statement every time.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS vocabulary_terms (
  vocabulary_term_id                  TEXT                 PRIMARY KEY          -- Stored logical identifier for one VocabularyTerms row.
);
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS vocabulary TEXT;                              -- Vocabulary this term belongs to.
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS pref_label TEXT;                              -- SKOS preferred label — the controlled term itself.
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS alt_labels TEXT;                              -- Comma-separated synonyms this term should also match.
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS definition TEXT;                              -- SKOS definition of what this term means.
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                       -- Extension class IRI.
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS scope_note TEXT;                              -- SKOS scope note: how the concept is to be used.
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS broader_term TEXT;                            -- Direct broader concept (skos:broader).
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS concept_iri TEXT;                             -- Globally unique IRI of the concept.
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS namespace_iri TEXT;                           -- Namespace the concept belongs to.
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS same_as_iri TEXT;                             -- External term this concept is asserted identical to (owl:sameAs).
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS introduced_in_release TEXT;                   -- Model release that introduced the concept.
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS represents_role TEXT;                         -- For a role-vocabulary concept, the role it names.
ALTER TABLE vocabulary_terms ADD COLUMN IF NOT EXISTS definition_revised_at TIMESTAMPTZ;            -- When the definition was last revised.
COMMENT ON TABLE vocabulary_terms IS 'One controlled, defined term (a SKOS Concept) within a Vocabulary. Requirements point at a VocabularyTerm instead of free-texting the same concept in a new Statement every time.';
COMMENT ON COLUMN vocabulary_terms.vocabulary_term_id IS 'Stored logical identifier for one VocabularyTerms row.';
COMMENT ON COLUMN vocabulary_terms.vocabulary IS 'Vocabulary this term belongs to.';
COMMENT ON COLUMN vocabulary_terms.pref_label IS 'SKOS preferred label — the controlled term itself.';
COMMENT ON COLUMN vocabulary_terms.alt_labels IS 'Comma-separated synonyms this term should also match.';
COMMENT ON COLUMN vocabulary_terms.definition IS 'SKOS definition of what this term means.';
COMMENT ON COLUMN vocabulary_terms.semantic_type_iri IS 'Extension class IRI.';
COMMENT ON COLUMN vocabulary_terms.scope_note IS 'SKOS scope note: how the concept is to be used.';
COMMENT ON COLUMN vocabulary_terms.broader_term IS 'Direct broader concept (skos:broader).';
COMMENT ON COLUMN vocabulary_terms.concept_iri IS 'Globally unique IRI of the concept.';
COMMENT ON COLUMN vocabulary_terms.namespace_iri IS 'Namespace the concept belongs to.';
COMMENT ON COLUMN vocabulary_terms.same_as_iri IS 'External term this concept is asserted identical to (owl:sameAs).';
COMMENT ON COLUMN vocabulary_terms.introduced_in_release IS 'Model release that introduced the concept.';
COMMENT ON COLUMN vocabulary_terms.represents_role IS 'For a role-vocabulary concept, the role it names.';
COMMENT ON COLUMN vocabulary_terms.definition_revised_at IS 'When the definition was last revised.';

-- ----------------------------------------------------------------------------
-- KnowledgeBrokerLinks: An informal expertise-network edge: one agent naming another as who they actually go to for a topic, independent of any formal Role or RoleAssignment. RoleAssignments and CommunitiesOfPractice record who is SUPPOSED to know something; this records who people ACTUALLY rely on.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS knowledge_broker_links (
  knowledge_broker_link_id            TEXT                 PRIMARY KEY          -- Stored logical identifier for one KnowledgeBrokerLinks row.
);
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS seeker TEXT;                            -- The agent who goes to someone else for this topic.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS broker TEXT;                            -- The agent who is actually consulted, whether or not they hold a formal role for it.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS topic TEXT;                             -- The controlled topic this reliance is about.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS frequency TEXT;                         -- Rarely, Sometimes, or Often.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS last_consulted_at TIMESTAMPTZ;          -- When the seeker last actually consulted the broker on this topic.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                -- The evaluation context this row's time-dependent witnesses are judged under.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                 -- Extension class IRI.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS points_to_know_how TEXT;                -- The know-how the broker points the seeker to.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS seeker_vocabulary TEXT;                 -- The vocabulary the seeker's community speaks.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS seeker_wording TEXT;                    -- The seeker's word for the topic.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS holder_vocabulary TEXT;                 -- The vocabulary of the community holding the know-how.
ALTER TABLE knowledge_broker_links ADD COLUMN IF NOT EXISTS holder_wording TEXT;                    -- The holding community's word for the topic.
COMMENT ON TABLE knowledge_broker_links IS 'An informal expertise-network edge: one agent naming another as who they actually go to for a topic, independent of any formal Role or RoleAssignment. RoleAssignments and CommunitiesOfPractice record who is SUPPOSED to know something; this records who people ACTUALLY rely on.';
COMMENT ON COLUMN knowledge_broker_links.knowledge_broker_link_id IS 'Stored logical identifier for one KnowledgeBrokerLinks row.';
COMMENT ON COLUMN knowledge_broker_links.seeker IS 'The agent who goes to someone else for this topic.';
COMMENT ON COLUMN knowledge_broker_links.broker IS 'The agent who is actually consulted, whether or not they hold a formal role for it.';
COMMENT ON COLUMN knowledge_broker_links.topic IS 'The controlled topic this reliance is about.';
COMMENT ON COLUMN knowledge_broker_links.frequency IS 'Rarely, Sometimes, or Often.';
COMMENT ON COLUMN knowledge_broker_links.last_consulted_at IS 'When the seeker last actually consulted the broker on this topic.';
COMMENT ON COLUMN knowledge_broker_links.evaluation_context IS 'The evaluation context this row''s time-dependent witnesses are judged under.';
COMMENT ON COLUMN knowledge_broker_links.semantic_type_iri IS 'Extension class IRI.';
COMMENT ON COLUMN knowledge_broker_links.points_to_know_how IS 'The know-how the broker points the seeker to.';
COMMENT ON COLUMN knowledge_broker_links.seeker_vocabulary IS 'The vocabulary the seeker''s community speaks.';
COMMENT ON COLUMN knowledge_broker_links.seeker_wording IS 'The seeker''s word for the topic.';
COMMENT ON COLUMN knowledge_broker_links.holder_vocabulary IS 'The vocabulary of the community holding the know-how.';
COMMENT ON COLUMN knowledge_broker_links.holder_wording IS 'The holding community''s word for the topic.';

-- ----------------------------------------------------------------------------
-- ConformanceSubstrates: Every tool that compiles this rulebook into something that computes. One is the answer-key author (compile-rulebook bakes derived values into the rulebook's own rows); the rest are graded substrates that re-derive those values natively and are scored cell by cell against them.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS conformance_substrates (
  conformance_substrate_id            TEXT                 PRIMARY KEY          -- Substrate name as the conformance harness knows it, e.g. 'effortless-python'.
);
ALTER TABLE conformance_substrates ADD COLUMN IF NOT EXISTS label TEXT;                             -- Short human label, e.g. 'Python'.
ALTER TABLE conformance_substrates ADD COLUMN IF NOT EXISTS transpiler TEXT;                        -- The effortless.json tool that produces this substrate, e.g. 'rulebook-to-python'.
ALTER TABLE conformance_substrates ADD COLUMN IF NOT EXISTS output_folder TEXT;                     -- Project folder the tool writes into, e.g. '/effortless-python'.
ALTER TABLE conformance_substrates ADD COLUMN IF NOT EXISTS engine TEXT;                            -- What actually evaluates the formulas: a database, a language runtime, a spreadsheet engine or a reasoner.
ALTER TABLE conformance_substrates ADD COLUMN IF NOT EXISTS how_it_computes TEXT;                   -- One paragraph a curious reader can follow: what the tool emits and how the harness makes it produce answers.
ALTER TABLE conformance_substrates ADD COLUMN IF NOT EXISTS role TEXT;                              -- 'answer-key' for the tool whose stored values every other substrate is graded against; 'graded' for everything else.
ALTER TABLE conformance_substrates ADD COLUMN IF NOT EXISTS sort_order NUMERIC;                     -- Display order.
ALTER TABLE conformance_substrates ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                 -- Semantic type IRI.
COMMENT ON TABLE conformance_substrates IS 'Every tool that compiles this rulebook into something that computes. One is the answer-key author (compile-rulebook bakes derived values into the rulebook''s own rows); the rest are graded substrates that re-derive those values natively and are scored cell by cell against them.';
COMMENT ON COLUMN conformance_substrates.conformance_substrate_id IS 'Substrate name as the conformance harness knows it, e.g. ''effortless-python''.';
COMMENT ON COLUMN conformance_substrates.label IS 'Short human label, e.g. ''Python''.';
COMMENT ON COLUMN conformance_substrates.transpiler IS 'The effortless.json tool that produces this substrate, e.g. ''rulebook-to-python''.';
COMMENT ON COLUMN conformance_substrates.output_folder IS 'Project folder the tool writes into, e.g. ''/effortless-python''.';
COMMENT ON COLUMN conformance_substrates.engine IS 'What actually evaluates the formulas: a database, a language runtime, a spreadsheet engine or a reasoner.';
COMMENT ON COLUMN conformance_substrates.how_it_computes IS 'One paragraph a curious reader can follow: what the tool emits and how the harness makes it produce answers.';
COMMENT ON COLUMN conformance_substrates.role IS '''answer-key'' for the tool whose stored values every other substrate is graded against; ''graded'' for everything else.';
COMMENT ON COLUMN conformance_substrates.sort_order IS 'Display order.';
COMMENT ON COLUMN conformance_substrates.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- ConformanceRuns: One execution of the conformance harness over every graded substrate. Kept as history; exactly one run is marked IsLatest, and the per-table, per-field and per-cell detail tables describe that run.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS conformance_runs (
  conformance_run_id                  TEXT                 PRIMARY KEY          -- Stored logical identifier, e.g. 'run-20260913-171500'.
);
ALTER TABLE conformance_runs ADD COLUMN IF NOT EXISTS ran_on TIMESTAMPTZ;                           -- When the harness graded the substrates.
ALTER TABLE conformance_runs ADD COLUMN IF NOT EXISTS rulebook_commit TEXT;                         -- git HEAD of the repository when the run was recorded; the rulebook may also carry uncommitted edits, noted in Notes.
ALTER TABLE conformance_runs ADD COLUMN IF NOT EXISTS answer_key_author TEXT;                       -- The substrate whose stored values were the answer keys for this run.
ALTER TABLE conformance_runs ADD COLUMN IF NOT EXISTS is_latest BOOLEAN;                            -- True for the most recent recorded run only. The recorder moves it.
ALTER TABLE conformance_runs ADD COLUMN IF NOT EXISTS notes TEXT;                                   -- Anything a reader needs to interpret the run.
ALTER TABLE conformance_runs ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                       -- Semantic type IRI.
COMMENT ON TABLE conformance_runs IS 'One execution of the conformance harness over every graded substrate. Kept as history; exactly one run is marked IsLatest, and the per-table, per-field and per-cell detail tables describe that run.';
COMMENT ON COLUMN conformance_runs.conformance_run_id IS 'Stored logical identifier, e.g. ''run-20260913-171500''.';
COMMENT ON COLUMN conformance_runs.ran_on IS 'When the harness graded the substrates.';
COMMENT ON COLUMN conformance_runs.rulebook_commit IS 'git HEAD of the repository when the run was recorded; the rulebook may also carry uncommitted edits, noted in Notes.';
COMMENT ON COLUMN conformance_runs.answer_key_author IS 'The substrate whose stored values were the answer keys for this run.';
COMMENT ON COLUMN conformance_runs.is_latest IS 'True for the most recent recorded run only. The recorder moves it.';
COMMENT ON COLUMN conformance_runs.notes IS 'Anything a reader needs to interpret the run.';
COMMENT ON COLUMN conformance_runs.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- SubstrateRunScores: One substrate's grade in one conformance run, split by field class so a substrate that does scalar math natively but not cross-table joins reads as exactly that.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS substrate_run_scores (
  substrate_run_score_id              TEXT                 PRIMARY KEY          -- Stored logical identifier: '<run>|<substrate>'.
);
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS run TEXT;                                 -- The run that produced this grade.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS substrate TEXT;                           -- The substrate graded.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS harness_error TEXT;                       -- Why the substrate could not be run, verbatim from the harness. Blank when it ran.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS duration_seconds NUMERIC;                 -- Wall-clock seconds to produce answers.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS cells_tested NUMERIC;                     -- Every (record x derived field) pair in the answer keys.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS cells_passed NUMERIC;                     -- Cells matching the answer key.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS calculated_tested NUMERIC;                -- Cells of calculated (same-row formula) fields.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS calculated_passed NUMERIC;                -- Calculated cells that matched.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS lookup_tested NUMERIC;                    -- Cells of lookup (cross-table INDEX/MATCH) fields.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS lookup_passed NUMERIC;                    -- Lookup cells that matched.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS aggregation_tested NUMERIC;               -- Cells of aggregation (COUNTIFS/SUMIFS rollup) fields.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS aggregation_passed NUMERIC;               -- Aggregation cells that matched.
ALTER TABLE substrate_run_scores ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                   -- Semantic type IRI.
COMMENT ON TABLE substrate_run_scores IS 'One substrate''s grade in one conformance run, split by field class so a substrate that does scalar math natively but not cross-table joins reads as exactly that.';
COMMENT ON COLUMN substrate_run_scores.substrate_run_score_id IS 'Stored logical identifier: ''<run>|<substrate>''.';
COMMENT ON COLUMN substrate_run_scores.run IS 'The run that produced this grade.';
COMMENT ON COLUMN substrate_run_scores.substrate IS 'The substrate graded.';
COMMENT ON COLUMN substrate_run_scores.harness_error IS 'Why the substrate could not be run, verbatim from the harness. Blank when it ran.';
COMMENT ON COLUMN substrate_run_scores.duration_seconds IS 'Wall-clock seconds to produce answers.';
COMMENT ON COLUMN substrate_run_scores.cells_tested IS 'Every (record x derived field) pair in the answer keys.';
COMMENT ON COLUMN substrate_run_scores.cells_passed IS 'Cells matching the answer key.';
COMMENT ON COLUMN substrate_run_scores.calculated_tested IS 'Cells of calculated (same-row formula) fields.';
COMMENT ON COLUMN substrate_run_scores.calculated_passed IS 'Calculated cells that matched.';
COMMENT ON COLUMN substrate_run_scores.lookup_tested IS 'Cells of lookup (cross-table INDEX/MATCH) fields.';
COMMENT ON COLUMN substrate_run_scores.lookup_passed IS 'Lookup cells that matched.';
COMMENT ON COLUMN substrate_run_scores.aggregation_tested IS 'Cells of aggregation (COUNTIFS/SUMIFS rollup) fields.';
COMMENT ON COLUMN substrate_run_scores.aggregation_passed IS 'Aggregation cells that matched.';
COMMENT ON COLUMN substrate_run_scores.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- TableConformance: Latest run only: how one substrate did on one table. The grid of these rows is the substrate-by-table heatmap.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS table_conformance (
  table_conformance_id                TEXT                 PRIMARY KEY          -- Stored logical identifier: '<substrate>|<Table>'.
);
ALTER TABLE table_conformance ADD COLUMN IF NOT EXISTS run TEXT;                                    -- The run this row describes.
ALTER TABLE table_conformance ADD COLUMN IF NOT EXISTS substrate TEXT;                              -- The substrate graded.
ALTER TABLE table_conformance ADD COLUMN IF NOT EXISTS rulebook_table TEXT;                         -- The table graded.
ALTER TABLE table_conformance ADD COLUMN IF NOT EXISTS record_count NUMERIC;                        -- Rows in the answer key for this table.
ALTER TABLE table_conformance ADD COLUMN IF NOT EXISTS derived_field_count NUMERIC;                 -- Derived fields graded on this table.
ALTER TABLE table_conformance ADD COLUMN IF NOT EXISTS cells_tested NUMERIC;                        -- RecordCount x DerivedFieldCount.
ALTER TABLE table_conformance ADD COLUMN IF NOT EXISTS cells_passed NUMERIC;                        -- Cells matching the answer key.
ALTER TABLE table_conformance ADD COLUMN IF NOT EXISTS is_missing_answer_file BOOLEAN;              -- True when the substrate produced no answers for this table at all; every cell then counts as failed.
ALTER TABLE table_conformance ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                      -- Semantic type IRI.
COMMENT ON TABLE table_conformance IS 'Latest run only: how one substrate did on one table. The grid of these rows is the substrate-by-table heatmap.';
COMMENT ON COLUMN table_conformance.table_conformance_id IS 'Stored logical identifier: ''<substrate>|<Table>''.';
COMMENT ON COLUMN table_conformance.run IS 'The run this row describes.';
COMMENT ON COLUMN table_conformance.substrate IS 'The substrate graded.';
COMMENT ON COLUMN table_conformance.rulebook_table IS 'The table graded.';
COMMENT ON COLUMN table_conformance.record_count IS 'Rows in the answer key for this table.';
COMMENT ON COLUMN table_conformance.derived_field_count IS 'Derived fields graded on this table.';
COMMENT ON COLUMN table_conformance.cells_tested IS 'RecordCount x DerivedFieldCount.';
COMMENT ON COLUMN table_conformance.cells_passed IS 'Cells matching the answer key.';
COMMENT ON COLUMN table_conformance.is_missing_answer_file IS 'True when the substrate produced no answers for this table at all; every cell then counts as failed.';
COMMENT ON COLUMN table_conformance.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- FieldDisagreements: Latest run only: a derived field on which one substrate got at least one cell wrong. A field with no row here agreed everywhere. CellsFailed is the true count; CellDisagreements holds a sample of the cells.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS field_disagreements (
  field_disagreement_id               TEXT                 PRIMARY KEY          -- Stored logical identifier: '<substrate>|<Table>.<Field>'.
);
ALTER TABLE field_disagreements ADD COLUMN IF NOT EXISTS substrate TEXT;                            -- The substrate that disagreed.
ALTER TABLE field_disagreements ADD COLUMN IF NOT EXISTS rulebook_field TEXT;                       -- The field it disagreed on.
ALTER TABLE field_disagreements ADD COLUMN IF NOT EXISTS table_conformance TEXT;                    -- The substrate-by-table row this field belongs to.
ALTER TABLE field_disagreements ADD COLUMN IF NOT EXISTS field_class TEXT;                          -- calculated, lookup or aggregation.
ALTER TABLE field_disagreements ADD COLUMN IF NOT EXISTS cells_failed NUMERIC;                      -- Every cell of this field the substrate got wrong, not just the sampled ones.
ALTER TABLE field_disagreements ADD COLUMN IF NOT EXISTS dominant_reason TEXT;                      -- The harness's most frequent reason: 'wrong/null value', 'missing record' or 'missing entity file'.
ALTER TABLE field_disagreements ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                    -- Semantic type IRI.
COMMENT ON TABLE field_disagreements IS 'Latest run only: a derived field on which one substrate got at least one cell wrong. A field with no row here agreed everywhere. CellsFailed is the true count; CellDisagreements holds a sample of the cells.';
COMMENT ON COLUMN field_disagreements.field_disagreement_id IS 'Stored logical identifier: ''<substrate>|<Table>.<Field>''.';
COMMENT ON COLUMN field_disagreements.substrate IS 'The substrate that disagreed.';
COMMENT ON COLUMN field_disagreements.rulebook_field IS 'The field it disagreed on.';
COMMENT ON COLUMN field_disagreements.table_conformance IS 'The substrate-by-table row this field belongs to.';
COMMENT ON COLUMN field_disagreements.field_class IS 'calculated, lookup or aggregation.';
COMMENT ON COLUMN field_disagreements.cells_failed IS 'Every cell of this field the substrate got wrong, not just the sampled ones.';
COMMENT ON COLUMN field_disagreements.dominant_reason IS 'The harness''s most frequent reason: ''wrong/null value'', ''missing record'' or ''missing entity file''.';
COMMENT ON COLUMN field_disagreements.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- CellDisagreements: Latest run only: one cell a substrate computed differently from the answer key, with both values verbatim. Sampled per field; see FieldDisagreements.IsFullySampled.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cell_disagreements (
  cell_disagreement_id                TEXT                 PRIMARY KEY          -- Stored logical identifier: '<substrate>|<Table>.<Field>|<record id>'.
);
ALTER TABLE cell_disagreements ADD COLUMN IF NOT EXISTS field_disagreement TEXT;                    -- The substrate-by-field disagreement this cell belongs to.
ALTER TABLE cell_disagreements ADD COLUMN IF NOT EXISTS record_id TEXT;                             -- Primary key of the row whose cell disagreed.
ALTER TABLE cell_disagreements ADD COLUMN IF NOT EXISTS expected_value TEXT;                        -- The answer key's value, JSON-encoded so null, '', false and 0 stay distinguishable.
ALTER TABLE cell_disagreements ADD COLUMN IF NOT EXISTS actual_value TEXT;                          -- The substrate's value, JSON-encoded the same way.
ALTER TABLE cell_disagreements ADD COLUMN IF NOT EXISTS reason TEXT;                                -- The harness's reason: 'wrong/null value', 'missing record' or 'missing entity file'.
ALTER TABLE cell_disagreements ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                     -- Semantic type IRI.
COMMENT ON TABLE cell_disagreements IS 'Latest run only: one cell a substrate computed differently from the answer key, with both values verbatim. Sampled per field; see FieldDisagreements.IsFullySampled.';
