COMMENT ON COLUMN cell_disagreements.record_id IS 'Primary key of the row whose cell disagreed.';
COMMENT ON COLUMN cell_disagreements.expected_value IS 'The answer key''s value, JSON-encoded so null, '''', false and 0 stay distinguishable.';
COMMENT ON COLUMN cell_disagreements.actual_value IS 'The substrate''s value, JSON-encoded the same way.';
COMMENT ON COLUMN cell_disagreements.reason IS 'The harness''s reason: ''wrong/null value'', ''missing record'' or ''missing entity file''.';
COMMENT ON COLUMN cell_disagreements.semantic_type_iri IS 'Semantic type IRI.';

