-- ----------------------------------------------------------------------------
-- GovernedModels: Everything under governance: this rulebook as an ontology, each procedure family, and each governed vocabulary.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS governed_models (
  governed_model_id                   TEXT                 PRIMARY KEY          -- Stored identifier.
);
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS label TEXT;                                    -- What is governed.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS model_kind TEXT;                               -- Ontology, ProcedureFamily or Vocabulary.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS procedure TEXT;                                -- For a procedure family, the procedure.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS domain_owning_organization TEXT;               -- The function that owns the domain being modeled.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS tooling_owner_role TEXT;                       -- Role that owns the knowledge-infrastructure tooling the model is built and published with.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS organization_headcount INTEGER;                -- Headcount of the organization governing the model.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS requirements_purpose TEXT;                     -- Requirements specification: the model's purpose.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS intended_users TEXT;                           -- Requirements specification: the model's intended users.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS registered_at TIMESTAMPTZ;                     -- When the model came under management.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS first_control_adopted_at TIMESTAMPTZ;          -- When the first governance control other than ownership was adopted.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS current_charter TEXT;                          -- Key of the charter currently in force, blank when none.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS current_release TEXT;                          -- Key of the release the model is currently declared at.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                       -- Evaluation context.
ALTER TABLE governed_models ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                        -- Semantic type IRI.
