ALTER TABLE sourcing_functions ADD COLUMN IF NOT EXISTS work_nature TEXT;                           -- Transactional (routine) or ExpertiseHeavy (analytical, design or engineering judgment).
ALTER TABLE sourcing_functions ADD COLUMN IF NOT EXISTS is_strategically_vital BOOLEAN;             -- TRUE when the organization cannot deliver its strategy without the function.
ALTER TABLE sourcing_functions ADD COLUMN IF NOT EXISTS delivers_own_product BOOLEAN;               -- TRUE when the function is part of delivering the organization's own products.
ALTER TABLE sourcing_functions ADD COLUMN IF NOT EXISTS executing_organization TEXT;                -- The organization that actually performs the work.
ALTER TABLE sourcing_functions ADD COLUMN IF NOT EXISTS specification_holder TEXT;                  -- The party that holds what is to be built or delivered.
