ALTER TABLE sourcing_functions ADD COLUMN IF NOT EXISTS sourced_since TIMESTAMPTZ;                  -- When the current execution arrangement began.
ALTER TABLE sourcing_functions ADD COLUMN IF NOT EXISTS sourcing_rationale TEXT;                    -- Why the function was placed where it is (CoreCompetencyFocus, CostReduction, Capability).
ALTER TABLE sourcing_functions ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                     -- Semantic type IRI.
