COMMENT ON COLUMN assignment_routed_notices.routed_to_agent IS 'Who received it; blank when nobody did.';
COMMENT ON COLUMN assignment_routed_notices.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- PractitionerExpertise: Expertise a practitioner demonstrably holds, with the basis they could not put into words recorded as a property of that knowledge source.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS practitioner_expertise (
  practitioner_expertise_id           TEXT                 PRIMARY KEY          -- Stored identifier.
);
ALTER TABLE practitioner_expertise ADD COLUMN IF NOT EXISTS agent TEXT;                             -- The practitioner who holds the expertise.
ALTER TABLE practitioner_expertise ADD COLUMN IF NOT EXISTS procedure TEXT;                         -- The procedure the expertise is exercised in.
ALTER TABLE practitioner_expertise ADD COLUMN IF NOT EXISTS step TEXT;                              -- The step the expertise is exercised at.
ALTER TABLE practitioner_expertise ADD COLUMN IF NOT EXISTS elicitation_session TEXT;               -- The session in which the expertise was probed.
ALTER TABLE practitioner_expertise ADD COLUMN IF NOT EXISTS expert_kind TEXT;                       -- Detection (sensing a condition in the moment) or DesignForesight (sensing a future cost).
ALTER TABLE practitioner_expertise ADD COLUMN IF NOT EXISTS cue TEXT;                               -- What the practitioner senses or judges.
ALTER TABLE practitioner_expertise ADD COLUMN IF NOT EXISTS unstated_basis TEXT;                    -- The basis the practitioner could not articulate, in the elicitor's words; blank when the basis was stated.
ALTER TABLE practitioner_expertise ADD COLUMN IF NOT EXISTS reliable_call_count INTEGER;            -- Observed occasions on which the practitioner's call proved right.
ALTER TABLE practitioner_expertise ADD COLUMN IF NOT EXISTS foresight_confirmed BOOLEAN;            -- For design foresight: TRUE when later experience confirmed the call.
ALTER TABLE practitioner_expertise ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                 -- Semantic type IRI.
