COMMENT ON COLUMN practitioner_expertise.reliable_call_count IS 'Observed occasions on which the practitioner''s call proved right.';
COMMENT ON COLUMN practitioner_expertise.foresight_confirmed IS 'For design foresight: TRUE when later experience confirmed the call.';
COMMENT ON COLUMN practitioner_expertise.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- CriticalIncidents: Specific past episodes of a procedure that went well, went badly or needed improvising, collected with the critical incident technique, each linked to the judgment call it brought out.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS critical_incidents (
  critical_incident_id                TEXT                 PRIMARY KEY          -- Stored identifier.
);
ALTER TABLE critical_incidents ADD COLUMN IF NOT EXISTS procedure_version TEXT;                     -- The version the episode is elicited for.
