ALTER TABLE critical_incidents ADD COLUMN IF NOT EXISTS account TEXT;                               -- The practitioner's account of the episode.
ALTER TABLE critical_incidents ADD COLUMN IF NOT EXISTS revealed_judgment TEXT;                     -- The judgment call the episode brought out that the written procedure hides; blank when none.
ALTER TABLE critical_incidents ADD COLUMN IF NOT EXISTS judgment_fragment TEXT;                     -- The knowledge fragment the revealed judgment was recorded as.
ALTER TABLE critical_incidents ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                     -- Semantic type IRI.
