COMMENT ON COLUMN critical_incidents.occurred_at IS 'When the episode happened.';
COMMENT ON COLUMN critical_incidents.outcome IS 'WentWell, WentBadly or Improvised.';
COMMENT ON COLUMN critical_incidents.account IS 'The practitioner''s account of the episode.';
COMMENT ON COLUMN critical_incidents.revealed_judgment IS 'The judgment call the episode brought out that the written procedure hides; blank when none.';
COMMENT ON COLUMN critical_incidents.judgment_fragment IS 'The knowledge fragment the revealed judgment was recorded as.';
COMMENT ON COLUMN critical_incidents.semantic_type_iri IS 'Semantic type IRI.';

