ALTER TABLE observed_actions ADD COLUMN IF NOT EXISTS action_kind TEXT;                             -- SmallChoice, Workaround, OmittedObviousStep or DocumentedStep.
ALTER TABLE observed_actions ADD COLUMN IF NOT EXISTS mentioned_in_own_account BOOLEAN;             -- TRUE when the practitioner's own interview account included the action.
ALTER TABLE observed_actions ADD COLUMN IF NOT EXISTS stated_reason TEXT;                           -- The reason the practitioner gave when the observer asked; blank when nobody asked.
ALTER TABLE observed_actions ADD COLUMN IF NOT EXISTS counterfactual_condition TEXT;                -- The different condition the observer asked about.
ALTER TABLE observed_actions ADD COLUMN IF NOT EXISTS counterfactual_answer TEXT;                   -- What the practitioner said they would do under that condition.
ALTER TABLE observed_actions ADD COLUMN IF NOT EXISTS captured_as_fragment TEXT;                    -- The knowledge fragment the action was captured as.
ALTER TABLE observed_actions ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                       -- Semantic type IRI.
