ALTER TABLE elicitation_participants ADD COLUMN IF NOT EXISTS process_stake TEXT;                   -- Initiates, Executes or DependsOnResults; blank for a facilitator with no stake.
ALTER TABLE elicitation_participants ADD COLUMN IF NOT EXISTS is_usually_invited BOOLEAN;           -- FALSE for a participant whose position is normally left out of such sessions.
ALTER TABLE elicitation_participants ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;               -- Semantic type IRI.
