COMMENT ON COLUMN elicitation_participants.knowledge_flow IS 'Producer, Consumer or Both.';
COMMENT ON COLUMN elicitation_participants.process_stake IS 'Initiates, Executes or DependsOnResults; blank for a facilitator with no stake.';
COMMENT ON COLUMN elicitation_participants.is_usually_invited IS 'FALSE for a participant whose position is normally left out of such sessions.';
COMMENT ON COLUMN elicitation_participants.semantic_type_iri IS 'Semantic type IRI.';

