COMMENT ON COLUMN workflow_view_divergences.view_b IS 'The differing account.';
COMMENT ON COLUMN workflow_view_divergences.holder_b IS 'Who holds the second account.';
COMMENT ON COLUMN workflow_view_divergences.reconciled_statement IS 'The account the participants settled on; blank while unsettled.';
COMMENT ON COLUMN workflow_view_divergences.reconciled_at IS 'When it was settled.';
