COMMENT ON COLUMN workflow_view_divergences.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- ExpertCognitions: Mental models and decision heuristics experts apply, drawn out by protocols and incident interviews, with any exceptions the expert stated and whether the capture kept them.
