ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS requirement TEXT;                             -- The constraint traced, when the target is a requirement.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS source_material TEXT;                         -- The collected material the knowledge traces to.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS trace_role TEXT;                              -- Origin (knowledge was taken from it), Validates, Extends, or Contradicts.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS traced_aspect TEXT;                           -- What the source is cited for: Sequence, StepDescription, Workaround, ActualExecution or Constraint.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS source_statement TEXT;                        -- Paraphrase of what the source says about the target.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS derivation_route TEXT;                        -- How the knowledge was produced from the source.
