ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS contradicted_document TEXT;                   -- For a contradiction: the document whose prescription practice departs from.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                       -- Semantic type IRI.
COMMENT ON TABLE knowledge_traces IS 'One trace from a piece of organized knowledge (a process model, an activity definition or a constraint) to the collected material it rests on, with the role the material plays (origin, validation, extension, contradiction), how the knowledge was derived, and who confirmed it.';
