ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS recorded_stance TEXT;                         -- Observed (kept as mined behavior) or Intended (recorded as intended process logic).
ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS intent_decision_by TEXT;                      -- Who decided that mined behavior should become intended logic.
ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                       -- Semantic type IRI.
COMMENT ON TABLE mined_flow_edges IS 'One step-to-step hand-off reconstructed from a system event log by a process-mining run: how many cases took it, how long cases waited before the next step, and whether it is kept as observed behavior or recorded as intended logic.';
