COMMENT ON COLUMN mined_flow_edges.observed_case_count IS 'Cases in the log that took this hand-off.';
COMMENT ON COLUMN mined_flow_edges.median_wait_minutes IS 'Median minutes between leaving FromStep and starting ToStep.';
COMMENT ON COLUMN mined_flow_edges.recorded_stance IS 'Observed (kept as mined behavior) or Intended (recorded as intended process logic).';
COMMENT ON COLUMN mined_flow_edges.intent_decision_by IS 'Who decided that mined behavior should become intended logic.';
COMMENT ON COLUMN mined_flow_edges.semantic_type_iri IS 'Semantic type IRI.';

