-- ----------------------------------------------------------------------------
-- AppActions: One row per thing a role may DO in the app: the base table it writes, the operation, the access policy that permits it, and the derived value the page highlights afterwards. The app has no per-action endpoint; it executes these rows.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS app_actions (
  app_action_id                       TEXT                 PRIMARY KEY          -- Stable key, e.g. act-tech-start-lockout.
);
ALTER TABLE app_actions ADD COLUMN IF NOT EXISTS label TEXT;                                        -- The button's words.
ALTER TABLE app_actions ADD COLUMN IF NOT EXISTS owning_role TEXT;                                  -- The role that performs this action.
