ALTER TABLE app_actions ADD COLUMN IF NOT EXISTS target_table TEXT;                                 -- The base table written.
ALTER TABLE app_actions ADD COLUMN IF NOT EXISTS operation TEXT;                                    -- INSERT or UPDATE, spelled as the policy's Command is.
ALTER TABLE app_actions ADD COLUMN IF NOT EXISTS policy TEXT;                                       -- The write policy that permits it. Blank means nothing permits it.
ALTER TABLE app_actions ADD COLUMN IF NOT EXISTS watched_field TEXT;                                -- The derived value the page highlights after the write.
ALTER TABLE app_actions ADD COLUMN IF NOT EXISTS story_episode INTEGER;                             -- The episode of the video series that performs this action on camera.
ALTER TABLE app_actions ADD COLUMN IF NOT EXISTS description TEXT;                                  -- What the action means, in the role's words.
ALTER TABLE app_actions ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                            -- Extension IRI.
COMMENT ON TABLE app_actions IS 'One row per thing a role may DO in the app: the base table it writes, the operation, the access policy that permits it, and the derived value the page highlights afterwards. The app has no per-action endpoint; it executes these rows.';
COMMENT ON COLUMN app_actions.app_action_id IS 'Stable key, e.g. act-tech-start-lockout.';
COMMENT ON COLUMN app_actions.label IS 'The button''s words.';
COMMENT ON COLUMN app_actions.owning_role IS 'The role that performs this action.';
COMMENT ON COLUMN app_actions.route_path IS 'The app route the action appears on.';
COMMENT ON COLUMN app_actions.target_table IS 'The base table written.';
COMMENT ON COLUMN app_actions.operation IS 'INSERT or UPDATE, spelled as the policy''s Command is.';
COMMENT ON COLUMN app_actions.policy IS 'The write policy that permits it. Blank means nothing permits it.';
COMMENT ON COLUMN app_actions.watched_field IS 'The derived value the page highlights after the write.';
COMMENT ON COLUMN app_actions.story_episode IS 'The episode of the video series that performs this action on camera.';
COMMENT ON COLUMN app_actions.description IS 'What the action means, in the role''s words.';
COMMENT ON COLUMN app_actions.semantic_type_iri IS 'Extension IRI.';

-- ----------------------------------------------------------------------------
-- AppActionFields: The fields one action writes, one row each, and where each value comes from: typed by the person, picked from a list, fixed by the action, or stamped by the server.
