ALTER TABLE app_action_fields ADD COLUMN IF NOT EXISTS fixed_value TEXT;                            -- For fixed: the value. For server: what is stamped (agent, instant, id, iri).
ALTER TABLE app_action_fields ADD COLUMN IF NOT EXISTS choices_from TEXT;                           -- For choice: the table whose rows are offered.
