-- ----------------------------------------------------------------------------
-- AbundantKnowledgeGaps: The kinds of knowledge that an abundance of information does not supply, each pointing at the table in this model that represents it. One row per kind named in the source material's 'paradox of abundant knowledge'.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS abundant_knowledge_gaps (
  abundant_knowledge_gap_id           TEXT                 PRIMARY KEY          -- Readable key for the kind of knowledge.
);
ALTER TABLE abundant_knowledge_gaps ADD COLUMN IF NOT EXISTS label TEXT;                            -- Short name of this kind of knowledge.
