ALTER TABLE abundant_knowledge_gaps ADD COLUMN IF NOT EXISTS description TEXT;                      -- What this kind of knowledge is.
ALTER TABLE abundant_knowledge_gaps ADD COLUMN IF NOT EXISTS why_abundance_does_not_supply_it TEXT; -- Why having more information available does not produce this kind of knowledge.
ALTER TABLE abundant_knowledge_gaps ADD COLUMN IF NOT EXISTS represented_by_table TEXT;             -- The table in this model that holds this kind of knowledge.
ALTER TABLE abundant_knowledge_gaps ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                -- Semantic type.
COMMENT ON TABLE abundant_knowledge_gaps IS 'The kinds of knowledge that an abundance of information does not supply, each pointing at the table in this model that represents it. One row per kind named in the source material''s ''paradox of abundant knowledge''.';
COMMENT ON COLUMN abundant_knowledge_gaps.abundant_knowledge_gap_id IS 'Readable key for the kind of knowledge.';
COMMENT ON COLUMN abundant_knowledge_gaps.label IS 'Short name of this kind of knowledge.';
COMMENT ON COLUMN abundant_knowledge_gaps.gap_kind IS 'HumanJudgment | UndiscoveredTacitKnowledge | CuratedToUserAndUseCase.';
COMMENT ON COLUMN abundant_knowledge_gaps.description IS 'What this kind of knowledge is.';
COMMENT ON COLUMN abundant_knowledge_gaps.why_abundance_does_not_supply_it IS 'Why having more information available does not produce this kind of knowledge.';
COMMENT ON COLUMN abundant_knowledge_gaps.represented_by_table IS 'The table in this model that holds this kind of knowledge.';
COMMENT ON COLUMN abundant_knowledge_gaps.semantic_type_iri IS 'Semantic type.';

-- ----------------------------------------------------------------------------
-- OntologySupportProgrammes: Funded research programmes that produced or supported the ontologies this model reuses. Recorded so the ontology authority can see what happens to a reused vocabulary when the programme behind it ends.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ontology_support_programmes (
  ontology_support_programme_id       TEXT                 PRIMARY KEY          -- Readable key for the programme.
);
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS label TEXT;                        -- Full programme title.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS acronym TEXT;                      -- Programme acronym.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS funder TEXT;                       -- Body that funded the programme.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS grant_reference TEXT;              -- Grant agreement number, as published by the funder.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS programme_iri TEXT;                -- Public record of the programme.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS coordinator TEXT;                  -- Organization coordinating the programme.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS started_on TIMESTAMPTZ;            -- Programme start date, as published by the funder.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS ends_on TIMESTAMPTZ;               -- Programme end date, as published by the funder.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS is_industry_focused BOOLEAN;       -- Whether the programme's purpose is ontology development for industry.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS our_successor_steward TEXT;        -- Who this organization relies on to maintain the terms it took from this programme once the programme ends. Blank means nobody has been named.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS why_recorded TEXT;                 -- Why the ontology authority tracks this programme, whether or not anything has been adopted from it yet.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS evaluation_context TEXT;           -- The instant this row is judged against.
ALTER TABLE ontology_support_programmes ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;            -- Semantic type.
COMMENT ON TABLE ontology_support_programmes IS 'Funded research programmes that produced or supported the ontologies this model reuses. Recorded so the ontology authority can see what happens to a reused vocabulary when the programme behind it ends.';
COMMENT ON COLUMN ontology_support_programmes.ontology_support_programme_id IS 'Readable key for the programme.';
COMMENT ON COLUMN ontology_support_programmes.label IS 'Full programme title.';
COMMENT ON COLUMN ontology_support_programmes.acronym IS 'Programme acronym.';
COMMENT ON COLUMN ontology_support_programmes.funder IS 'Body that funded the programme.';
COMMENT ON COLUMN ontology_support_programmes.grant_reference IS 'Grant agreement number, as published by the funder.';
COMMENT ON COLUMN ontology_support_programmes.programme_iri IS 'Public record of the programme.';
COMMENT ON COLUMN ontology_support_programmes.coordinator IS 'Organization coordinating the programme.';
COMMENT ON COLUMN ontology_support_programmes.started_on IS 'Programme start date, as published by the funder.';
COMMENT ON COLUMN ontology_support_programmes.ends_on IS 'Programme end date, as published by the funder.';
COMMENT ON COLUMN ontology_support_programmes.is_industry_focused IS 'Whether the programme''s purpose is ontology development for industry.';
COMMENT ON COLUMN ontology_support_programmes.our_successor_steward IS 'Who this organization relies on to maintain the terms it took from this programme once the programme ends. Blank means nobody has been named.';
COMMENT ON COLUMN ontology_support_programmes.why_recorded IS 'Why the ontology authority tracks this programme, whether or not anything has been adopted from it yet.';
COMMENT ON COLUMN ontology_support_programmes.evaluation_context IS 'The instant this row is judged against.';
COMMENT ON COLUMN ontology_support_programmes.semantic_type_iri IS 'Semantic type.';

